INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 1, 1, 'زمستان در راه است', 'Winter Is Coming', '2011-04-17', 61, 'لرد ند استارک، ارباب وینترفل، از فرار یک دشمن از نگهبانان شب مطلع می‌شود. شاه رابرت باراتیون برای درخواست از ند برای سمت دست، به وینترفل می‌آید. در آن سوی دنیا، ویسریس تارگرن خواهرش دنریس را به عقد رهبر دثراکی‌ها، کال دروگو، درمی‌آورد تا ارتشی برای پس گرفتن تخت آهنین به دست آورد.'),
(11, 1, 2, 'جاده شاهی', 'The Kingsroad', '2011-04-24', 56, 'ند به همراه دخترانش سانسا و آریا، شاه رابرت را تا کینگز لندینگ همراهی می‌کند. کتلین استارک در وینترفل می‌ماند. جان اسنو، پسر نامشروع ند، به همراه عمویش بنجن به سمت دیوار می‌رود تا به نگهبانان شب بپیوندد. تیریون لنیستر نیز تصمیم می‌گیرد با آنها همراه شود.'),
(11, 1, 3, 'برف ارباب', 'Lord Snow', '2011-05-01', 58, 'ند در کینگز لندینگ با اوضاع آشفته دربار روبرو می‌شود. جان اسنو در قلعه سیاه، آموزش خود را زیر نظر فرمانده خشمگین آغاز می‌کند. آریا زیر نظر سیریو فارل، استاد شمشیرزنی، تمرینات خود را شروع می‌کند. دنریس در میان دثراکی‌ها احساس غربت می‌کند و برادرش ویسریس طلا و جواهرات او را می‌دزدد.'),
(11, 1, 4, 'فلج‌ها، حرامزاده‌ها و چیزهای شکسته', 'Cripples, Bastards, and Broken Things', '2011-05-08', 56, 'ند در حال تحقیق درباره مرگ جان آرین، دست سابق شاه، است. تیریون از ند سئوال می‌کند که آیا می‌تواند به برادرش جای پاداشی که در جنگ مستحق آن است بدهد. جان به دوستی به نام سمول تارلی، جوانی ترسو که به نگهبانان شب پیوسته، نزدیک می‌شود.'),
(11, 1, 5, 'گرگ و شیر', 'The Wolf and the Lion', '2011-05-15', 55, 'کتلین استارک، آریا و سانسا، و تیریون را در مسافرخانه‌ای می‌بیند و او را به اتهام تلاش برای قتل برن، پسرش، دستگیر می‌کند. تیریون خواستار محاکمه از طریق مبارزه می‌شود و برنده می‌شود. در کینگز لندینگ، ند با رابرت بر سر نقشه قتل دنریس مشاجره می‌کند و از سمت خود استعفا می‌دهد.'),
(11, 1, 6, 'تاج طلایی', 'A Golden Crown', '2011-05-22', 53, 'رابرت در حین شکار به شدت مجروح می‌شود. در باریک‌آب، کاتلین و تیریون به دربار لیسا آرین می‌رسند. تیریون با استفاده از یک مزدور، خواستار محاکمه از طریق مبارزه می‌شود و برنده می‌شود. در ویس دثراک، ویسریس سعی می‌کند شمشیری را بدزدد تا هزینه سفرش را بپردازد، اما دنریس او را متوقف می‌کند و عنوان "تاج طلایی" را به او هدیه می‌دهد.'),
(11, 1, 7, 'یا می‌بری یا می‌میری', 'You Win or You Die', '2011-05-29', 58, 'در کینگز لندینگ، جوفری باراتیون پس از مرگ رابرت، به عنوان پادشاه جدید معرفی می‌شود. ند ادعا می‌کند که جوفری پسر واقعی رابرت نیست و وارث واقعی استانیس است. سرسی دستور دستگیری ند را می‌دهد. در آن سوی دیوار، جان و بقیه سوگندهای خود را می‌خوانند. دنریس می‌آموزد که شوهرش قصد دارد برای فتح هفت‌پادشاهی به وستروس حمله کند.'),
(11, 1, 8, 'نهایت تیزی', 'The Pointy End', '2011-06-05', 59, 'نیروهای لنیستر به خانه استارک در وینترفل حمله می‌کنند. راب استارک سپاهی از شمالی‌ها جمع می‌کند و به سمت جنوب به راه می‌افتد. آریا موفق به فرار می‌شود اما سانسا به گروگان گرفته می‌شود. جان در حال ترک نگهبانان شب است که توسط دوستانش متوقف می‌شود.'),
(11, 1, 9, 'بیلور', 'Baelor', '2011-06-12', 57, 'ند در زندان با گروگان گرفتن سانسا و به رسمیت شناختن جوفری به عنوان وارث تخت آهنین، آزادی خود را تضمین می‌کند. در محوطه بیلور، جوفری دستور اعدام ند را می‌دهد و او با شمشیر خودش اعدام می‌شود.'),
(11, 1, 10, 'آتش و خون', 'Fire and Blood', '2011-06-19', 55, 'شمال تحت رهبری راب استارک در حال تدارک جنگ است. اسلاورز بی (خلیج بردگان) شاهد قدرت دنریس است. دنریس در مراسم تشییع جنازه کال دروگو، تخم‌های اژدها را داخل آتش می‌گذارد و با فداکاری جادوگر، سه اژدها از تخم بیرون می‌آیند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 2, 1, 'شمال فراموش نمی‌کند', 'The North Remembers', '2012-04-01', 53, 'پس از مرگ ند استارک، برادرش راب پادشاه شمال اعلام می‌شود. در کینگز لندینگ، تیریون به عنوان دست موقت معرفی می‌شود و با توطئه‌های سرسی روبرو می‌شود. استانیس باراتیون ادعای تاج و تخت می‌کند.'),
(11, 2, 2, 'سرزمین‌های شب', 'The Night Lands', '2012-04-08', 54, 'در کینگز لندینگ، تیریون به دنبال کشف جاسوس ملکه مادر است. آریا و دوستانش در راه هارنهال با گروهی از پسرعموهایش روبرو می‌شوند. جان اسنو در راه دیوار با ایگریت، زنی وحشی، روبرو می‌شود.'),
(11, 2, 3, 'آنچه مرده است، هرگز نمی‌میرد', 'What Is Dead May Never Die', '2012-04-15', 58, 'تیریون در شورای کوچک به دنبال متحد است. در پییک، تئون گریجوی وارد معامله‌ای خطرناک با پدرش می‌شود. در کوآرت، دنریس از ورود به پادشاهی خودداری می‌کند.'),
(11, 2, 4, 'باغ استخوان', 'Garden of Bones', '2012-04-22', 51, 'در هارنهال، آریا شاهد اعمال ظالمانه سربازان لنیستر است. دنریس به شهر کوآرت می‌رسد و با توطئه جادوگران روبرو می‌شود. استانیس با رنلی گفتگو می‌کند.'),
(11, 2, 5, 'شبح هارنهال', 'The Ghost of Harrenhal', '2012-04-29', 55, 'تیریون به دنبال سلاحی مخفی در کینگز لندینگ است. آریا با جقن هقار روبرو می‌شود که سه نام به او می‌دهد. دنریس در جستجوی کشتی برای بازگشت به وستروس است.'),
(11, 2, 6, 'خدایان قدیم و جدید', 'The Old Gods and the New', '2012-05-06', 54, 'تئون وینترفل را تصرف می‌کند. در کینگز لندینگ، شورش علیه جوفری آغاز می‌شود. جان اسنو ایگریت را اسیر می‌کند. دنریس از شهر کوآرت رانده می‌شود.'),
(11, 2, 7, 'مردی بدون افتخار', 'A Man Without Honor', '2012-05-13', 56, 'در وینترفل، تئون دو پسر کشاورز را می‌کشد و وانمود می‌کند که برن و ریکون را کشته است. در هارنهال، آریا سرنخی از نقشه بران می‌یابد.'),
(11, 2, 8, 'شاهزاده وینترفل', 'The Prince of Winterfell', '2012-05-20', 54, 'در وینترفل، برن و ریکون از دست تئون فرار می‌کنند. در کینگز لندینگ، تیریون برای آخرین نبرد آماده می‌شود. در آن سوی دیوار، جان اسنو ایگریت را رها می‌کند.'),
(11, 2, 9, 'آب سیاه', 'Blackwater', '2012-05-27', 55, 'استانیس به کینگز لندینگ حمله می‌کند. تیریون از آتش وحشی برای نابودی ناوگان استانیس استفاده می‌کند. سرسی در حال مسموم کردن خود و پسرانش است. در نهایت، تیریون به شدت زخمی می‌شود و پدرش تیوین با ارتش خود وارد شهر می‌شود.'),
(11, 2, 10, 'والار مرغولیس', 'Valar Morghulis', '2012-06-03', 64, 'جوفری با مارگاری تایرل نامزد می‌شود. دنریس اژدهای خود را در کوآرت آزاد می‌کند. آریا با جقن هقار خداحافظی می‌کند و در راه بازگشت به وینترفل است.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 3, 1, 'والار دوهیریس', 'Valar Dohaeris', '2013-03-31', 55, 'جان اسنو پیش منس ریدر، پادشاه آن سوی دیوار، برده می‌شود. دنریس به شهر اسلاورز بی می‌رسد. تیریون پس از نبرد آب سیاه، از پدرش پاداش می‌خواهد.'),
(11, 3, 2, 'بال‌های تاریک، کلمات تاریک', 'Dark Wings, Dark Words', '2013-04-07', 56, 'در راه، برن و دوستانش با جوجن و میرا رید ملاقات می‌کنند. راب استارک با یک زن شفابخش ازدواج می‌کند. دنریس با فرمانده ناقوس‌ها دیدار می‌کند.'),
(11, 3, 3, 'قدمگاه مجازات', 'Walk of Punishment', '2013-04-14', 56, 'تیریون به عنوان استاد سکه منصوب می‌شود. دنریس با برده‌فروشان اسلاورز بی مذاکره می‌کند. جیمی در اسارت توسط یک زندانی دست راستش قطع می‌شود.'),
(11, 3, 4, 'و اکنون نگهبانی او به پایان رسیده است', 'And Now His Watch Is Ended', '2013-04-21', 53, 'در قلعه سیاه، سم ول به دنبال راهی برای درمان جور است. در اسلاورز بی، دنریس به برده‌ها وعده آزادی می‌دهد. جیمی و برین راهی کینگز لندینگ می‌شوند.'),
(11, 3, 5, 'بوسیده شده در آتش', 'Kissed by Fire', '2013-04-28', 56, 'در ریورران، راب با کارستارک‌ها برخورد می‌کند. در هارنهال، آریا تحت آموزش قرار می‌گیرد. در آن سوی دیوار، جان اسنو تصمیم به فرار می‌گیرد.'),
(11, 3, 6, 'صعود', 'The Climb', '2013-05-05', 54, 'در کینگز لندینگ، تیریون و سرسی با یکدیگر گفتگو می‌کنند. در آن سوی دیوار، جان اسنو و ایگریت از دیوار بالا می‌روند. در اسلاورز بی، دنریس با یک مهمان غیرمنتظره روبرو می‌شود.'),
(11, 3, 7, 'خرس و دوشیزه زیبا', 'The Bear and the Maiden Fair', '2013-05-12', 58, 'در ریورران، جیمی و برین قصد دارند به کینگز لندینگ برسند. در وینترفل، برن و ریکون از هم جدا می‌شوند. در هارنهال، آریا شاهد مرگ یکی از دوستانش است.'),
(11, 3, 8, 'پسران دوم', 'Second Sons', '2013-05-19', 56, 'در اسلاورز بی، دنریس با گروهی از مزدوران معامله می‌کند. در ریورران، راب برای ازدواج خود تصمیم می‌گیرد. در کینگز لندینگ، تیریون با سانسا ازدواج می‌کند.'),
(11, 3, 9, 'باران کاستامیر', 'The Rains of Castamere', '2013-06-02', 53, 'در عروسی ادمور تالی و یکی از دختران والدر فرای، خانواده استارک قتل عام می‌شوند. راب، همسرش تالیسا، مادرش کتلین و بسیاری از حامیان آنها کشته می‌شوند.'),
(11, 3, 10, 'میسا', 'Mhysa', '2013-06-09', 64, 'دنریس شهر یونکای را فتح می‌کند و برده‌ها او را مادر (میسا) می‌نامند. آریا در راه به یک دوست قدیمی می‌رسد. جان اسنو به قلعه سیاه بازمی‌گردد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 4, 1, 'دو شمشیر', 'Two Swords', '2014-04-06', 58, 'در کینگز لندینگ، تیوین دو شمشیر از شمشیر ناد استارک می‌سازد. در اسلاورز بی، دنریس با محاصره یونکای روبرو می‌شود. در آن سوی دیوار، جان اسنو به سرکشی نافرمانان می‌پردازد.'),
(11, 4, 2, 'شیر و رز', 'The Lion and the Rose', '2014-04-13', 52, 'در عروسی جوفری و مارگاری، جوفری مسموم می‌شود و در آغوش سرسی می‌میرد. تیریون به اتهام قتل دستگیر می‌شود.'),
(11, 4, 3, 'شکننده زنجیرها', 'Breaker of Chains', '2014-04-20', 56, 'تیریون در زندان به دنبال راهی برای نجات است. دنریس به شهر می‌رین می‌رسد. در دیوار، جان اسنو با مذاکره با وحشی‌ها روبرو می‌شود.'),
(11, 4, 4, 'نگاهبان سوگند', 'Oathkeeper', '2014-04-27', 54, 'جیمی برین را با شمشیر جدیدش آزاد می‌کند و او را به دنبال سانسا می‌فرستد. در اسلاورز بی، دنریس با شورشی روبرو می‌شود.'),
(11, 4, 5, 'اولین از نام خود', 'First of His Name', '2014-05-04', 54, 'تامن به عنوان پادشاه جدید تاج‌گذاری می‌کند. در یونکای، دنریس با مذاکره صلح با برده‌فروشان مواجه می‌شود. آریا و سندور راهی دره می‌شوند.'),
(11, 4, 6, 'قوانین خدایان و انسان‌ها', 'The Laws of Gods and Men', '2014-05-11', 51, 'تیریون در دادگاه محاکمه می‌شود. شاهدانی علیه او شهادت می‌دهند. تیریون در نهایت خواستار محاکمه از طریق مبارزه می‌شود.'),
(11, 4, 7, 'مرغ مقلد', 'Mockingbird', '2014-05-18', 54, 'در دره، پیتر بلیش لیسا آرین را از صخره بیرون می‌اندازد. تیریون در زندان با شاهزاده ابر دیدن می‌کند. دنریس با قوانین جدید یونکای مواجه می‌شود.'),
(11, 4, 8, 'کوه و افعی', 'The Mountain and the Viper', '2014-06-01', 52, 'در محاکمه تیریون، افعی (اوبرین مارتل) در مقابل کوه (گرگور کلگین) قرار می‌گیرد. اوبرین برنده می‌شود اما با بی احتیاطی، توسط کوه کشته می‌شود.'),
(11, 4, 9, 'نگهبانان بر دیوار', 'The Watchers on the Wall', '2014-06-08', 52, 'وحشی‌ها به دیوار حمله می‌کنند. جان اسنو رهبری دفاع را بر عهده می‌گیرد و با استفاده از تله‌های ماهرانه، حمله را دفع می‌کند.'),
(11, 4, 10, 'کودکان', 'The Children', '2014-06-15', 66, 'در دیوار، جان با منس ریدر دیدار می‌کند و او را می‌کشد. در آن سوی دیوار، برن و دوستانش به ریشه کهن می‌رسند. در می‌رین، دنریس اژدهای خود را زنجیر می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 5, 1, 'جنگ‌هایی که در پیش است', 'The Wars to Come', '2015-04-12', 52, 'در کینگز لندینگ، سرسی با خاندان تایرل رقابت می‌کند. در می‌رین، دنریس با شورش پسران هارپی روبرو می‌شود. لیتل فینگر سانسا را به وینترفل می‌برد.'),
(11, 5, 2, 'خانه سیاه و سفید', 'The House of Black and White', '2015-04-19', 56, 'آریا به براووس می‌رسد و به خانه سیاه و سفید می‌رود، جایی که می‌خواهد تحت آموزش قرار گیرد. در می‌رین، دنریس با یک عضو پسران هارپی روبرو می‌شود.'),
(11, 5, 3, 'گنجشک بالا', 'High Sparrow', '2015-04-26', 64, 'در کینگز لندینگ، سرسی با گنجشک‌ها (یک فرقه مذهبی) روبرو می‌شود. در می‌رین، دنریس با تقاضای تندر تارگارین، پسر بزرگ آئمون، برای بازگشت تارگارین، مواجه می‌شود.'),
(11, 5, 4, 'پسران هارپی', 'Sons of the Harpy', '2015-05-03', 52, 'در می‌رین، پسران هارپی به دنبال کشتن فرمانده ناقوس‌ها هستند. در کینگز لندینگ، سرسی توسط گنجشک بالا زندانی می‌شود.'),
(11, 5, 5, 'پسر را بکش', 'Kill the Boy', '2015-05-10', 57, 'در می‌رین، دنریس تصمیم می‌گیرد با برده‌فروشان همکاری کند. در کینگز لندینگ، تامن خواستار آزادی مادرش است.'),
(11, 5, 6, 'ناکم، ناشکسته، ناشکستنی', 'Unbowed, Unbent, Unbroken', '2015-05-17', 54, 'در کینگز لندینگ، سرسی با راهپیمایی شرمساری مواجه می‌شود. در دره، سانسا در شب عروسی خود توسط رمزی بولتون مورد آزار قرار می‌گیرد.'),
(11, 5, 7, 'هدیه', 'The Gift', '2015-05-24', 58, 'در کینگز لندینگ، سرسی اعتراف می‌کند و مجبور به راهپیمایی شرمساری می‌شود. در دیوار، جان اسنو با ارتش وحشی‌ها بازمی‌گردد.'),
(11, 5, 8, 'هاردهام', 'Hardhome', '2015-05-31', 59, 'جان اسنو و تورموند به هاردهام می‌روند تا وحشی‌ها را قانع کنند. او با فرمانده شب، نایت کینگ، روبرو می‌شود که ارتش مردگان را فرماندهی می‌کند.'),
(11, 5, 9, 'رقص اژدهایان', 'The Dance of Dragons', '2015-06-07', 52, 'در می‌رین، دنریس در حال تماشای نبرد در گودال اژدها است که پسران هارپی به آنها حمله می‌کنند. دنریس سوار بر دروگون فرار می‌کند.'),
(11, 5, 10, 'رحمت مادر', 'Mother''s Mercy', '2015-06-14', 64, 'در دیوار، جان اسنو توسط چند تن از نگهبانان شب خیانت می‌شود و به قتل می‌رسد. در کینگز لندینگ، سرسی با راهپیمایی شرمساری مجازات می‌شود. در سراسر وستروس، خبر مرگ جان اسنو پخش می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 6, 1, 'زن سرخپوش', 'The Red Woman', '2016-04-24', 52, 'در دیوار، ملیساندرا سعی می‌کند جان اسنو را زنده کند. در کینگز لندینگ، سرسی شاهد بازگشت دخترش میرسلا است، اما میرسلا مسموم می‌شود.'),
(11, 6, 2, 'خانه', 'Home', '2016-05-01', 54, 'در دیوار، ملیساندرا با استفاده از قدرت خود، جان اسنو را زنده می‌کند. در تویینفل، رمزی بولتون پدرش را می‌کشد.'),
(11, 6, 3, 'شکننده سوگند', 'Oathbreaker', '2016-05-08', 55, 'جان اسنو از نگهبانان شب خارج می‌شود. در دره، سانسا با پیتر بلیش دیدار می‌کند. در براووس، آریا در محاکمه قرار می‌گیرد.'),
(11, 6, 4, 'کتاب غریبه', 'Book of the Stranger', '2016-05-15', 57, 'در می‌رین، دنریس قصد بازگشت به پادشاهی را دارد. در وینترفل، سانسا و جون اسنو با هم ملاقات می‌کنند و قصد بازپس‌گیری وینترفل را دارند.'),
(11, 6, 5, 'در', 'The Door', '2016-05-22', 56, 'در آن سوی دیوار، برن در حال دیدن رؤیایی است که مشخص می‌شود چگونه نگهبانان شب ایجاد شده‌اند و همچنین راز پدربزرگش را می‌یابد.'),
(11, 6, 6, 'خون از خون من', 'Blood of My Blood', '2016-05-29', 54, 'در آن سوی دیوار، برن در حال فرار است. در می‌رین، دنریس سوار بر اژدهایش می‌شود و ارتش خود را جمع می‌کند.'),
(11, 6, 7, 'مرد شکسته', 'The Broken Man', '2016-06-05', 51, 'در ریورلندز، چند نفر از خانواده استارک بازمی‌گردند. در دره، پیتر بلیش سانسا را تهدید می‌کند.'),
(11, 6, 8, 'هیچ کس', 'No One', '2016-06-12', 59, 'در براووس، آریا با دخترخوانده سرسی روبرو می‌شود. در ریورلندز، برین از سانسا در مقابل دشمنان دفاع می‌کند.'),
(11, 6, 9, 'نبرد حرامزاده‌ها', 'Battle of the Bastards', '2016-06-19', 60, 'در وینترفل، جون اسنو و سانسا با ارتش رمزی بولتون می‌جنگند. در نهایت، با ورود شوالیه‌های دره، نبرد به نفع استارک‌ها تمام می‌شود.'),
(11, 6, 10, 'بادهای زمستان', 'The Winds of Winter', '2016-06-26', 69, 'در کینگز لندینگ، سرسی با استفاده از آتش وحشی، گنجشک بالا و بسیاری از دشمنانش را می‌کشد. در شمال، جون اسنو به عنوان پادشاه شمال معرفی می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 7, 1, 'دراگون استون', 'Dragonstone', '2017-07-16', 60, 'دنریس به دراگون استون می‌رسد و با مشاوران خود برنامه‌ریزی می‌کند. در شمال، جان اسنو مرگ و دشمن جدید را اعلام می‌کند.'),
(11, 7, 2, 'طوفان‌زاده', 'Stormborn', '2017-07-23', 57, 'دنریس به مشاوران خود درباره فتح هفت پادشاهی توضیح می‌دهد. در شمال، جان اسنو به دنبال متحدان برای مقابله با شب است.'),
(11, 7, 3, 'عدالت ملکه', 'The Queen''s Justice', '2017-07-30', 63, 'دنریس با مشاوران خود به کینگز لندینگ حمله می‌کند. در شمال، جان اسنو و دنریس با یکدیگر ملاقات می‌کنند.'),
(11, 7, 4, 'غنای جنگ', 'The Spoils of War', '2017-08-06', 50, 'دنریس سوار بر اژدهایش به ارتش لنیستر حمله می‌کند. در شمال، آریا به وینترفل بازمی‌گردد.'),
(11, 7, 5, 'ایستواچ', 'Eastwatch', '2017-08-13', 60, 'دنریس پس از نبرد، به مشاوران خود درباره تلفات می‌گوید. در شمال، جان اسنو به دنبال متحدان برای مقابله با شب است.'),
(11, 7, 6, 'آنسوی دیوار', 'Beyond the Wall', '2017-08-20', 70, 'جان اسنو و گروهش به آنسوی دیوار می‌روند تا یک وایت والکر را دستگیر کنند. در نهایت، دنریس سوار بر اژدهایش به کمک آنها می‌آید.'),
(11, 7, 7, 'اژدها و گرگ', 'The Dragon and the Wolf', '2017-08-27', 81, 'در کینگز لندینگ، سرسی با دنریس و جان اسنو ملاقات می‌کند. در کریپت وینترفل، جان اسنو حقیقت نسب خود را می‌یابد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(11, 8, 1, 'وینترفل', 'Winterfell', '2019-04-14', 54, 'دنریس و جان اسنو به وینترفل می‌رسند. خانواده‌های شمال با حضور آنها مشکوک هستند. سانسا استارک از دنریس استقبال می‌کند.'),
(11, 8, 2, 'شوالیه هفت پادشاهی', 'A Knight of the Seven Kingdoms', '2019-04-21', 58, 'شب قبل از نبرد وینترفل، شخصیت‌های اصلی با یکدیگر وداع می‌کنند. جیمی لنیستر برین تارث را شوالیه می‌کند.'),
(11, 8, 3, 'شب طولانی', 'The Long Night', '2019-04-28', 82, 'ارتش مردگان به وینترفل حمله می‌کند. آریا استارک با استفاده از چاقوی خنجر، پادشاه شب را می‌کشد و ارتش مردگان نابود می‌شود.'),
(11, 8, 4, 'آخرین استارک‌ها', 'The Last of the Starks', '2019-05-05', 78, 'پس از نبرد، مراسم خاکسپاری برگزار می‌شود. دنریس تصمیم می‌گیرد به کینگز لندینگ حمله کند.'),
(11, 8, 5, 'زنگ‌ها', 'The Bells', '2019-05-12', 80, 'دنریس به کینگز لندینگ حمله می‌کند و با وجود تسلیم شدن شهر، مردم عادی را قتل عام می‌کند. تیریون لنیستر دستور قتل دنریس را صادر می‌کند.'),
(11, 8, 6, 'تخت آهنین', 'The Iron Throne', '2019-05-19', 80, 'پس از مرگ دنریس، یک شورای بزرگ تشکیل می‌شود تا انتخاب کنند که چه کسی باید حاکم شود. برن استارک به عنوان پادشاه انتخاب می‌شود و شش پادشاهی را تشکیل می‌دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(12, 1, 1, 'پایلوت', 'Pilot', '2008-01-20', 58, 'والتر وایت، معلم شیمی، پس از تشخیص سرطان ریه، با شاگرد سابق خود جسی پینکمن برای تولید و فروش متامفتامین همکاری می‌کند.'),
(12, 1, 2, 'ماشین گربه در دانه', 'Cat''s in the Bag', '2008-01-27', 48, 'والتر و جسی با پیامدهای قتل امیلیو و کرایز هشتم دست و پنجه نرم می‌کنند و سعی می‌کنند بدن آنها را در اسید حل کنند.'),
(12, 1, 3, 'کیسه سفید', 'The Bag''s in the River', '2008-02-10', 48, 'والتر با یک انتخاب اخلاقی روبرو می‌شود وقتی کراچر هشتم گروگان را در زیرزمین نگهداری می‌کند و تصمیم می‌گیرد او را خفه کند.'),
(12, 1, 4, 'ماده خام', 'The Raw Material', '2008-02-17', 48, 'والتر و جسی سعی می‌کنند مواد اولیه شیمیایی مورد نیاز برای تولید مت را از یک انبار قطار بدزدند.'),
(12, 1, 5, 'ماده خاکستری', 'The Gray Matter', '2008-02-24', 48, 'والتر و اسکایلر به مهمانی بخصوصی می‌روند و والتر از دوست قدیمی خود الیوت شوارتز کمک مالی برای درمان سرطان می‌پذیرد.'),
(12, 1, 6, 'یک احمق دیوانه نیست', 'A No-Rough-Stuff-Type Deal', '2008-03-02', 48, 'والتر و جسی مواد خود را به توزیع کننده جدیدی به نام توکو سالامانکا می‌فروشند، اما توکو به جسی حمله می‌کند.'),
(12, 1, 7, 'حلقه فرمانروا', 'The Ruling Ring', '2008-03-09', 48, 'والتر و جسی پس از حمله توکو تصمیم می‌گیرند از شهر فرار کنند اما والتر به خانه بازمی‌گردد و با خانواده خود مواجه می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(12, 2, 1, 'هفت و سی و هفت', 'Seven Thirty-Seven', '2009-03-08', 48, 'والتر و جسی از دست توکو فرار می‌کنند و با مشکلات جدیدی مانند مواد منفجره و پول کثیف مواجه می‌شوند.'),
(12, 2, 2, 'کباب شده', 'Grilled', '2009-03-15', 48, 'توکو برادران سالامانکا را می‌کشد و والتر و جسی را می‌رباید. والتر با استفاده از مواد شیمیایی مسموم، توکو را می‌کشد.'),
(12, 2, 3, 'کمی ماده برای بچه', 'Bit by a Dead Bee', '2009-03-22', 48, 'والتر وانمود می‌کند که دچار فراموشی شده تا از دستگیری فرار کند. در همین حال، هانک سعی می‌کند مدرک جدیدی پیدا کند.'),
(12, 2, 4, 'پایین', 'Down', '2009-03-29', 48, 'والتر و اسکایلر در حال بازسازی روابط خود هستند. جسی توسط دوست دخترش جین از خانه بیرون انداخته می‌شود.'),
(12, 2, 5, 'شکست', 'Breakage', '2009-04-05', 48, 'جسی تلاش می‌کند تجارت مواد را به تنهایی اداره کند، اما با مشکلات زیادی روبرو می‌شود.'),
(12, 2, 6, 'موجود در تاریکی', 'Undead', '2009-04-12', 48, 'والتر و جسی با راه‌اندازی آزمایشگاه جدید، مواد با خلوص ۹۹.۱ درصد تولید می‌کنند. مشکلات خانوادگی هانک بدتر می‌شود.'),
(12, 2, 7, 'حمله بهتریخته', 'Better Call Saul', '2009-04-19', 48, 'والتر و جسی وکیلی به نام سال گودمن را استخدام می‌کنند تا به آنها در حل مشکلات حقوقی کمک کند.'),
(12, 2, 8, 'من به دیدن مری می‌روم', 'I See You', '2009-04-26', 48, 'هانک هدف یک سوء قصد قرار می‌گیرد و به بیمارستان منتقل می‌شود. والتر سعی می‌کند با همسرش اسکایلر آشتی کند.'),
(12, 2, 9, '۴ روز بیرون', '4 Days Out', '2009-05-03', 48, 'والتر و جسی به صحرا می‌روند تا مواد تولید کنند اما ماشینشان خراب می‌شود. والتر در شرایط سخت، خود را نجات می‌دهد.'),
(12, 2, 10, 'پایان', 'Over', '2009-05-10', 48, 'والتر پس از اتمام درمان، سعی می‌کند زندگی عادی خود را از سر بگیرد اما با مشکلاتی از جمله مواد فروش جدید روبرو می‌شود.'),
(12, 2, 11, 'مندیلا', 'Mandala', '2009-05-17', 48, 'والتر و جسی با توزیع کننده جدیدی به نام گاس فرینگ آشنا می‌شوند که پیشنهاد خرید مواد آنها را با سود بالا می‌دهد.'),
(12, 2, 12, 'فونیکس', 'Phoenix', '2009-05-24', 48, 'والتر پس از دیدن جین در حال خفگی، او را نجات نمی‌دهد و اجازه می‌دهد بمیرد و جسی دچار بحران روحی می‌شود.'),
(12, 2, 13, 'ای بی کیو', 'ABQ', '2009-05-31', 48, 'پس از مرگ جین، پدرش که کنترلر هوایی است دچار اشتباه می‌شود و باعث سقوط دو هواپیما می‌گردد که تلفات زیادی برجای می‌گذارد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(12, 3, 1, 'هیچ چیز بیشتر', 'No Más', '2010-03-21', 48, 'والتر از تجارت مواد کناره‌گیری می‌کند و سعی می‌کند با خانواده خود آشتی کند. جسی در جلسات NA شرکت می‌کند.'),
(12, 3, 2, 'کابوس', 'Nightmare', '2010-03-28', 48, 'جسی سعی می‌کند مواد خود را به معتادان بفروشد اما با مشکلاتی روبرو می‌شود. والتر به همسرش می‌گوید که سرطانش در حال بهبود است.'),
(12, 3, 3, 'بوقلمون وحشی', 'Wild Turkey', '2010-04-04', 48, 'والتر با گاس برای بازگشت به تجارت مذاکره می‌کند. هانک با اختلال استرس پس از سانحه روبرو می‌شود.'),
(12, 3, 4, 'انتهای خط', 'Line End', '2010-04-11', 48, 'والتر به توافق با گاس می‌رسد و دوباره شروع به تولید مواد می‌کند. جسی از والدینش جدا می‌شود.'),
(12, 3, 5, 'شکارچی', 'Hunter', '2010-04-18', 48, 'هانک به دنبال والتر در صحرا می‌گردد و او را متوقف می‌کند. والتر به او دروغ می‌گوید و هانک او را آزاد می‌کند.'),
(12, 3, 6, 'ادامه بده', 'Go On', '2010-04-25', 48, 'والتر تولید مواد را در آزمایشگاه جدید گاس آغاز می‌کند. جسی در جلسات NA با دختری به نام آندریا آشنا می‌شود.'),
(12, 3, 7, 'پرواز', 'Fly', '2010-05-02', 48, 'والتر و جسی تمام شب را در آزمایشگاه صرف کشتن یک مگس می‌کنند که فکر می‌کنند مواد را آلوده می‌کند.'),
(12, 3, 8, 'من می‌بینم تو می‌بینی', 'I See You, You See Me', '2010-05-09', 48, 'والت و جسی در حال تطبیق با شرایط جدید هستند. هانک توسط برادران سالامانکا تهدید می‌شود.'),
(12, 3, 9, 'کافکا', 'Kafka', '2010-05-16', 48, 'والتر و جسی با درخواست گاس برای کشتن گیل روبرو می‌شوند. جسی استعفا می‌دهد.'),
(12, 3, 10, 'شاهد', 'Witness', '2010-05-23', 48, 'جسی توسط برادران سالامانکا تهدید می‌شود. والتر تصمیم می‌گیرد از او محافظت کند.'),
(12, 3, 11, 'نیم‌قدم', 'Half Step', '2010-05-30', 48, 'والتر سعی می‌کند جسی و خانواده را از دست برادران سالامانکا نجات دهد. والتر با گاس روبرو می‌شود.'),
(12, 3, 12, 'دقیقه‌ها', 'Minutes', '2010-06-06', 48, 'والتر با استفاده از یک وسیله نقلیه زرهی به برادران سالامانکا حمله می‌کند و آنها را می‌کشد. هانک شاهد این ماجرا می‌شود.'),
(12, 3, 13, 'فول مطلقه', 'Full Divorce', '2010-06-13', 48, 'والتر و اسکایلر طلاق می‌گیرند. گاس از والتر می‌خواهد تا به تولید مواد ادامه دهد در غیر این صورت خانواده‌اش را تهدید می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(12, 4, 1, 'کاتر', 'Cutter', '2011-07-17', 48, 'والتر و خانواده‌اش به خانه‌ای جدید نقل مکان می‌کنند. جسی پس از مرگ جین در مرکز بازپروری بستری می‌شود.'),
(12, 4, 2, 'سی و هشت اسنوب', 'Thirty-Eight Snub', '2011-07-24', 48, 'والتر یک اسلحه دستساز می‌سازد. جسی از مرکز بازپروری فرار می‌کند و به خانه‌اش بازمی‌گردد.'),
(12, 4, 3, 'باز کردن قفل', 'Open Lock', '2011-07-31', 48, 'والتر سعی می‌کرد بفهمد گاس چگونه مواد را جابجا می‌کند. جسی با آندریا و براک رابطه خود را ادامه می‌دهد.'),
(12, 4, 4, 'سنگ کبود', 'Blue Stone', '2011-08-07', 48, 'والتر و جسی سعی می‌کنند اشتباهات خود را جبران کنند. هانک به دنبال یک پرونده جدید است.'),
(12, 4, 5, 'مرداد', 'August', '2011-08-14', 48, 'والتر تولد ۵۲ سالگی خود را جشن می‌گیرد. هانک به والتر مشکوک می‌شود.'),
(12, 4, 6, 'ببر وحشی', 'Wild Tiger', '2011-08-21', 48, 'والتر با سوالات هانک روبرو می‌شود و به او دروغ می‌گوید. جسی و گاس رابطه نزدیکتری پیدا می‌کنند.'),
(12, 4, 7, 'مشکل حل شده', 'Problem Solve', '2011-08-28', 48, 'والتر سعی می‌کند گاس را بکشد اما نقشه او شکست می‌خورد. جسی از گاس برای کشتن گیل کمک می‌خواهد.'),
(12, 4, 8, 'هرمانوس', 'Hermanos', '2011-09-04', 48, 'هانک با کمک ماری و گومز به دنبال اطلاعاتی در مورد گاس می‌گردد و متوجه می‌شود گاس در گذشته با یک کارتل مواد مخدر در ارتباط بوده است.'),
(12, 4, 9, 'تبر', 'Axe', '2011-09-11', 48, 'والتر و جسی برنامه‌های خود را تغییر می‌دهند. گاس جسی را تهدید می‌کند که اگر به همکاری ادامه ندهد خانواده والتر را خواهد کشت.'),
(12, 4, 10, 'سلامتی', 'Health', '2011-09-18', 48, 'والتر از سلامت خود ناراضی است. جسی و مایک با یکدیگر برخورد می‌کنند. هانک متوجه می‌شود والتر دروغ می‌گوید.'),
(12, 4, 11, 'گوزن', 'Deer', '2011-09-25', 48, 'والتر و خانواده‌اش به یک اردوی خانوادگی می‌روند. جسی به این نتیجه می‌رسد که گاس به دنبال کشتن والتر است.'),
(12, 4, 12, 'گوزن دوم', 'Second Deer', '2011-10-02', 48, 'والتر و جسی با یکدیگر همکاری می‌کنند تا گاس را بکشند. هانک به نزدیک شدن به حقیقت ادامه می‌دهد.'),
(12, 4, 13, 'فیس آف', 'Face Off', '2011-10-09', 50, 'والتر با استفاده از یک بمب دست‌ساز در بیمارستان، هکتور را می‌کشد و گاس را نیز در انفجار می‌کشد. هانک متوجه می‌شود که والتر هایزنبرگ است.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(12, 5, 1, 'زنده باد پادشاه', 'Live Free or Die', '2012-07-15', 48, 'والتر پس از کشتن گاس، تجارت خود را گسترش می‌دهد. جسی از این وضعیت ناراضی است. هانک به تحقیقات خود ادامه می‌دهد.'),
(12, 5, 2, 'مادریگال', 'Madrigal', '2012-07-22', 48, 'والتر با شرکت مادریگال الکتروموتور همکاری می‌کند تا مواد خود را به اروپا صادر کند. جسی سعی می‌کند از این تجارت خارج شود.'),
(12, 5, 3, 'خطر', 'Hazard', '2012-07-29', 48, 'والتر و جسی با مشکلات جدیدی از جمله مایک و تواد روبرو می‌شوند. هانک متوجه می‌شود که والتر هایزنبرگ است.'),
(12, 5, 4, '۵۱', 'Fifty-One', '2012-08-05', 48, 'والتر تولد ۵۱ سالگی خود را جشن می‌گیرد. اسکایلر از او می‌خواهد که از خانواده دور بماند. جسی سعی می‌کند مواد را متوقف کند.'),
(12, 5, 5, 'کشته‌ها', 'Dead Weight', '2012-08-12', 48, 'والتر با مایک به دنبال یافتن فردی برای جایگزینی هستند. جسی با مایک برای پیدا کردن راهی برای متوقف کردن تولید همکاری می‌کند.'),
(12, 5, 6, 'خرید و فروش', 'Buyout', '2012-08-19', 48, 'والتر تجارت خود را به یک گروه جدید می‌فروشد. جسی از این تصمیم عصبانی است. هانک به نزدیک شدن به حقیقت ادامه می‌دهد.'),
(12, 5, 7, 'اسم من را بگو', 'Say My Name', '2012-08-26', 48, 'والتر با توزیع‌کننده جدیدی به نام دکلان ملاقات می‌کند. جسی تصمیم می‌گیرد از تجارت خارج شود. هانک با یک خبر روبرو می‌شود.'),
(12, 5, 8, 'بر فراز کوههای آلپ', 'Gliding Over All', '2012-09-02', 48, 'والتر ده نفر از همراهان مایک را در زندان‌های مختلف می‌کشد. هانک با کمک ماری متوجه می‌شود که والتر هایزنبرگ است.'),
(12, 5, 9, 'خون پول', 'Blood Money', '2013-08-11', 48, 'هانک با کمک ماری متوجه می‌شود که والتر هایزنبرگ است. والتر سعی می‌کند حقیقت را از خانواده پنهان کند.'),
(12, 5, 10, 'مدفون', 'Buried', '2013-08-18', 48, 'اسکایلر از والتر می‌خواهد که تسلیم شود. هانک سعی می‌کند مدارک کافی برای دستگیری والتر جمع‌آوری کند.'),
(12, 5, 11, 'اعترافات', 'Confessions', '2013-08-25', 48, 'والتر یک نوار اعتراف دروغین می‌سازد که در آن هانک را متهم به رهبری کارتل مواد مخدر می‌کند.'),
(12, 5, 12, 'خرگوش وحشی', 'Rabid Dog', '2013-09-01', 48, 'والتر پس از اینکه متوجه می‌شود جسی قصد دارد او را لو بدهد، سعی می‌کند جسی را بکشد. هانک و گومز به تعقیب والتر ادامه می‌دهند.'),
(12, 5, 13, 'توهالومی', 'To''hajiilee', '2013-09-08', 48, 'والتر با استفاده از جسی به عنوان طعمه، هانک و گومز را در بیابان به دام می‌اندازد. درگیری مسلحانه بین والتر و گروه هانک در می‌گیرد.'),
(12, 5, 14, 'اوزی ماندیاس', 'Ozymandias', '2013-09-15', 48, 'در درگیری مسلحانه، گومز کشته می‌شود و هانک توسط جک و گروه نئونازی‌ها به قتل می‌رسد. والتر فرار می‌کند و خانواده‌اش از او متنفر می‌شوند.'),
(12, 5, 15, 'گرانیت ایالت', 'Granite State', '2013-09-22', 48, 'والتر با هویت جدید در نیوهمپشایر پنهان می‌شود. جسی توسط جک و گروه نئونازی‌ها به بردگی گرفته می‌شود و مجبور به تولید مواد می‌شود.'),
(12, 5, 16, 'فینال', 'Felina', '2013-09-29', 55, 'والتر به نیومکزیکو بازمی‌گردد و با جک و گروهش روبرو می‌شود. او جک و افرادش را می‌کشد، جسی را آزاد می‌کند و خودش در اثر اصابت گلوله می‌میرد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(13, 1, 1, 'ناپدید شدن ویل بایرز', 'The Vanishing of Will Byers', '2016-07-15', 47, 'پسر جوانی به نام ویل بایرز در راه خانه از یک موجود ناشناس ربوده می‌شود. دوستانش مایک، داستین و لوکاس به دنبال او می‌گردند.'),
(13, 1, 2, 'دیوانه در خیابان مپل', 'The Weirdo on Maple Street', '2016-07-15', 55, 'پسرها دختر مرموزی به نام الون را پیدا می‌کنند. مادر ویل، جویس، سعی می‌کند با پسرش از طریق چراغ‌ها ارتباط برقرار کند.'),
(13, 1, 3, 'هالی، جالی', 'Holly, Jolly', '2016-07-15', 51, 'جویس و پلیس ارشد هاپر وارد دنیایی موازی به نام وارونه (آپساید داون) می‌شوند. الون از قدرت‌های تله‌کینتیک خود استفاده می‌کند.'),
(13, 1, 4, 'بدن', 'The Body', '2016-07-15', 50, 'هاپر و جویس بدن جعلی ویل را پیدا می‌کنند و متوجه می‌شوند که ممکن است ویل هنوز زنده باشد. پسرها به الون کمک می‌کنند.'),
(13, 1, 5, 'کک و آکروبات', 'The Flea and the Acrobat', '2016-07-15', 52, 'پسرها نظریه‌ای درباره وارونه ارائه می‌دهند. نانسی و جاناتان با یک دموگورگون روبرو می‌شوند.'),
(13, 1, 6, 'هیولا', 'The Monster', '2016-07-15', 46, 'نانسی و جاناتان تله‌ای برای دموگورگون می‌سازند. الون با یادآوری گذشته‌اش تلاش می‌کند ویل را پیدا کند.'),
(13, 1, 7, 'حمام', 'The Bathtub', '2016-07-15', 41, 'گروه برای پیدا کردن ویل از یک مخزن حسی (مخزن حسی) استفاده می‌کند. الون در وارونه با ویل ارتباط برقرار می‌کند.'),
(13, 1, 8, 'وارونه', 'The Upside Down', '2016-07-15', 55, 'گروه به وارونه سفر می‌کند و ویل را نجات می‌دهد. الون با دموگورگون مبارزه می‌کند و ناپدید می‌شود. ویل به خانه بازمی‌گردد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(13, 2, 1, 'مادمکس', 'MADMAX', '2017-10-27', 48, 'یک سال پس از وقایع فصل اول، مایک، داستین و لوکاس سعی می‌کنند زندگی عادی خود را از سر بگیرند. دختری جدید به نام مکس به جمع آنها می‌پیوندد.'),
(13, 2, 2, 'آبنبات‌های کدو تنبل', 'Trick or Treat, Freak', '2017-10-27', 56, 'در شب هالوین، ویل توسط نیروهای تاریک وارونه تسخیر می‌شود. گروه سعی می‌کند راز موجود جدیدی به نام شکارچی روح را کشف کند.'),
(13, 2, 3, 'بچه ماهی', 'The Pollywog', '2017-10-27', 51, 'داستین موجود کوچک و عجیبی را پیدا می‌کند و آن را دآرتنیس می‌نامد. نانسی و جاناتان برای افشای توطئه آزمایشگاه هاوکینز همکاری می‌کنند.'),
(13, 2, 4, 'ویل حکیم', 'Will the Wise', '2017-10-27', 46, 'ویل سعی می‌کند به دوستانش بگوید که شکارچی روح در حال نابودی دنیاست. الون برای پیدا کردن خواهرش کالی به شیکاگو سفر می‌کند.'),
(13, 2, 5, 'دیگ و داستین', 'Dig Dug', '2017-10-27', 59, 'داستین متوجه می‌شود که دآرتنیس به موجودی بزرگ و خطرناک تبدیل شده است. گروه برای متوقف کردن شکارچی روح وارد تونل‌های زیرزمینی می‌شوند.'),
(13, 2, 6, 'جاسوس', 'The Spy', '2017-10-27', 46, 'ویل تسخیر می‌شود و به عنوان جاسوس شکارچی روح عمل می‌کند. هاپر متوجه می‌شود که یک حمله بزرگ در راه است و شهر را تخلیه می‌کند.'),
(13, 2, 7, 'خواهر گمشده', 'The Lost Sister', '2017-10-27', 45, 'الون با خواهرش کالی ملاقات می‌کند و از او کمک می‌خواهد اما در نهایت تصمیم می‌گیرد به هاکینز بازگردد تا از دوستانش محافظت کند.'),
(13, 2, 8, 'شکارچی روح', 'The Mind Flayer', '2017-10-27', 48, 'الون به هاکینز بازمی‌گردد و برای نجات ویل و متوقف کردن شکارچی روح، وارد ذهن ویل می‌شود.'),
(13, 2, 9, 'دروازه', 'The Gate', '2017-10-27', 55, 'ارتش الون، مایک، مکس و بقیه برای بستن دروازه وارونه و نجات ویل با هم متحد می‌شوند. در نهایت، الون موفق می‌شود دروازه را ببندد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(13, 3, 1, 'سوزانا، حمام را خاموش کن', 'Suzie, Do You Copy?', '2019-07-04', 51, 'در تابستان ۱۹۸۵، یک مرکز خرید جدید به نام استارکورت مال در هاکینز افتتاح می‌شود. رازهای تاریکی در زیر آن پنهان شده است.'),
(13, 3, 2, 'موش‌های صحرایی', 'The Mall Rats', '2019-07-04', 50, 'گروهی از موش‌ها به طور مرموزی ناپدید می‌شوند. الون مشکوک می‌شود که ممکن است شکارچی روح بازگشته باشد.'),
(13, 3, 3, 'مورد از دست رفته', 'The Case of the Missing Lifeguard', '2019-07-04', 51, 'مکس و الون به دنبال یک غریق نجات گمشده می‌گردند و متوجه می‌شوند که او توسط یک نیروی شیطانی تصرف شده است.'),
(13, 3, 4, 'آزمایشگاه', 'The Sauna Test', '2019-07-04', 52, 'گروه مظنون است که بیلی توسط شکارچی روح تسخیر شده است. آنها او را در سونای استارکورت مال به دام می‌اندازند.'),
(13, 3, 5, 'قتل عام', 'The Flayed', '2019-07-04', 50, 'شمار قربانیان تسخیر شده توسط شکارچی روح افزایش می‌یابد. نانسی و جاناتان از بیمارستان هاکینز بازدید می‌کنند.'),
(13, 3, 6, 'بستنی‌های رنگارنگ', 'E Pluribus Unum', '2019-07-04', 59, 'شکارچی روح از بدن بیلی به عنوان میزبان اصلی خود استفاده می‌کند. الون و گروه سعی می‌کنند راهی برای متوقف کردن آن پیدا کنند.'),
(13, 3, 7, 'نیش', 'The Bite', '2019-07-04', 53, 'شکارچی روح به گروه بیل و گریگوری حمله می‌کند و الون را می‌رباید. دوستانش برای نجات او تلاش می‌کنند.'),
(13, 3, 8, 'نبرد استارکورت', 'The Battle of Starcourt', '2019-07-04', 59, 'نبرد نهایی بین گروه و شکارچی روح در استارکورت مال رخ می‌دهد. هاپر قربانی می‌شود و الون قدرت‌های خود را از دست می‌دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(13, 4, 1, 'باشگاه جهنم آتشین', 'The Hellfire Club', '2022-05-27', 76, 'الون در کالیفرنیا تحت تعقیب است و قدرت‌های خود را از دست داده. در هاکینز، قتل‌های مرموزی توسط موجودی به نام وکنا (Vecna) رخ می‌دهد.'),
(13, 4, 2, 'لطافت وکنا', 'Vecna''s Curse', '2022-05-27', 75, 'وکنا به قتل‌های خود ادامه می‌دهد. گروه سعی می‌کند الگوی حملات او را تشخیص دهد و قربانی بعدی را پیش‌بینی کند.'),
(13, 4, 3, 'هیولا و سوپرمن', 'The Monster and the Superhero', '2022-05-27', 63, 'مکس خود را در معرض خطر قرار می‌دهد تا وکنا را فریب دهد. الون و دکتر اوونس سعی می‌کنند قدرت‌های او را بازگردانند.'),
(13, 4, 4, 'بیلی عزیز', 'Dear Billy', '2022-05-27', 69, 'مکس در آستانه قربانی شدن توسط وکنا قرار دارد اما با یادآوری خاطرات خوب خود از بیلی، موفق به فرار می‌شود.'),
(13, 4, 5, 'پروژه نینجا', 'The Nina Project', '2022-05-27', 74, 'الون خاطرات خود را در آزمایشگاه هاکینز به یاد می‌آورد و نحوه ایجاد وکنا را کشف می‌کند.'),
(13, 4, 6, 'غواصی', 'The Dive', '2022-05-27', 65, 'گروه برای پیدا کردن ورودی وارونه به دریاچه می‌روند. استیو توسط خفاش‌های وارونه مورد حمله قرار می‌گیرد.'),
(13, 4, 7, 'قتلگاه', 'The Massacre at Hawkins Lab', '2022-05-27', 82, 'الون به یاد می‌آورد که چگونه وکنا (که هنری کریل نام دارد) در آزمایشگاه هاکینز قتل عام کرد و او بود که وکنا را به وارونه تبعید کرد.'),
(13, 4, 8, 'پاپا', 'Papa', '2022-07-01', 83, 'الون با دکتر برنر (پاپا) ملاقات می‌کند و از او درباره گذشته‌اش سوال می‌کند. هاپر از زندان روسیه فرار می‌کند.'),
(13, 4, 9, 'دوربین‌های مداربسته', 'The Piggyback', '2022-07-01', 139, 'الون برای مبارزه با وکنا وارد ذهن مکس می‌شود. در نهایت، الون موفق می‌شود وکنا را شکست دهد اما مکس در کما فرو می‌رود و زلزله‌ای هاکینز را ویران می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 1, 1, 'ولورتون', 'Wolferton', '2016-11-04', 58, 'پرنسس الیزابت در سال ۱۹۴۷ با فیلیپ مونتباتن ازدواج می‌کند. پدرش شاه جرج ششم با مشکلات سلامتی روبرو است.'),
(14, 1, 2, 'هاید پارک کورنر', 'Hyde Park Corner', '2016-11-04', 54, 'شاه جرج ششم در سن ۵۶ سالگی می‌میرد و الیزابت در سن ۲۵ سالگی ملکه بریتانیا می‌شود.'),
(14, 1, 3, 'ویندزور', 'Windsor', '2016-11-04', 56, 'ملکه الیزابت سعی می‌کند با نقش جدید خود کنار بیاید. خواهرش پرنسس مارگارت از او می‌خواهد که اجازه ازدواج با پیتر تاونسند را بدهد.'),
(14, 1, 4, 'جواهرات تاج', 'Crown Jewels', '2016-11-04', 58, 'وینستون چرچیل، نخست‌وزیر پیر، سعی می‌کند با قدرت بماند در حالی که ملکه سعی می‌کند جایگاه خود را پیدا کند.'),
(14, 1, 5, 'دود تفنگ', 'Smoke and Mirrors', '2016-11-04', 52, 'ملکه خود را برای تاج‌گذاری آماده می‌کند. روابط بین خانواده سلطنتی و دولت چرچیل تیره می‌شود.'),
(14, 1, 6, 'ژلوسیا', 'Gelignite', '2016-11-04', 55, 'پرنسس مارگارت به درخواست ازدواج با پیتر تاونسند اصرار می‌ورزد. ملکه و چرچیل با یکدیگر مشورت می‌کنند.'),
(14, 1, 7, 'دانش بشردوستی', 'Scientia Potentia Est', '2016-11-04', 54, 'ملکه متوجه می‌شود که از تحصیلات مناسب برخوردار نیست و سعی می‌کند یک معلم خصوصی برای خود پیدا کند.'),
(14, 1, 8, 'شرم و افتخار', 'Pride & Joy', '2016-11-04', 57, 'فیلیپ به عنوان فرمانده کشتی مشغول به کار می‌شود و از نفوذ ملکه برای پیشرفت شغلی خود استفاده می‌کند.'),
(14, 1, 9, 'تپه مرغان', 'Assassins', '2016-11-04', 58, 'اتحاد جماهیر شوروی سلاح هسته‌ای آزمایش می‌کند و چرچیل با بحران سلامتی روبرو می‌شود.'),
(14, 1, 10, 'سایه‌های غم', 'Gloomy Sunday', '2016-11-04', 55, 'ملکه و چرچیل با یکدیگر ملاقات می‌کنند. چرچیل در نهایت استعفا می‌دهد و آنتونی ایدن جانشین او می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 2, 1, 'آسیب‌های ناشی از اشتباهات', 'Misadventure', '2017-12-08', 59, 'بحران سوئز روابط ملکه و نخست‌وزیر آنتونی ایدن را تیره می‌کند. فیلیپ در سفری طولانی ملکه را ترک می‌کند.'),
(14, 2, 2, 'مردی در کمد', 'A Company of Men', '2017-12-08', 55, 'ملکه سعی می‌کند نقش جنسیتی خود و فیلیپ را مشخص کند. فیلیپ در سفری به استرالیا دوستان جدیدی پیدا می‌کند.'),
(14, 2, 3, 'لیسبون', 'Lisbon', '2017-12-08', 56, 'پرنسس مارگارت با آنتونی آرمسترانگ جونز ازدواج می‌کند. ملکه سعی می‌کند خواهرش را شاد کند.'),
(14, 2, 4, 'بریژیتو', 'Beryl', '2017-12-08', 58, 'پرنسس مارگارت از زندگی با آنتونی ناراضی است و با یک عکاس دیگر رابطه برقرار می‌کند.'),
(14, 2, 5, 'ماریونت‌ها', 'Marionettes', '2017-12-08', 57, 'نخست‌وزیر جدید هارولد مک‌میلان با بحران‌های سیاسی روبرو می‌شود و ملکه سعی می‌کند او را مدیریت کند.'),
(14, 2, 6, 'وراثت', 'Vergangenheit', '2017-12-08', 55, 'ملکه و فیلیپ به آلمان سفر می‌کنند. ملکه سعی می‌کود روابط با آلمان را بهبود بخشد.'),
(14, 2, 7, 'مردم بی‌اطلاع', 'Matrimonium', '2017-12-08', 59, 'ملکه به اختلافات خانوادگی خود و فیلیپ رسیدگی می‌کند. روابط آنها در شرف فروپاشی است.'),
(14, 2, 8, 'دوست عزیز', 'Dear Mrs. Kennedy', '2017-12-08', 54, 'ملکه با ژاکلین کندی، بانوی اول ایالات متحده، ملاقات می‌کند و تحت تأثیر جذابیت و سبک او قرار می‌گیرد.'),
(14, 2, 9, 'زن ناشناس', 'Paterfamilias', '2017-12-08', 56, 'فیلیپ با گذشته خود روبرو می‌شود و سعی می‌کند پسرش چارلز را برای آینده آماده کند.'),
(14, 2, 10, 'راز', 'Mystery Man', '2017-12-08', 52, 'پروفسور جان پروفومو، وزیر جنگ، در یک رسوایی جنسی درگیر می‌شود که دولت مک‌میلان را تضعیف می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 3, 1, 'اولدینگ', 'Olding', '2019-11-17', 56, 'هارولد ویلسون نخست‌وزیر جدید می‌شود. جمعیت بریتانیا از خانواده سلطنتی انتقاد می‌کند و ملکه نگران آینده سلطنت است.'),
(14, 3, 2, 'مارگارتولوژی', 'Margaretology', '2019-11-17', 57, 'پرنسس مارگارت به همراه ملکه به ایالات متحده سفر می‌کند و شخصیت پر زرق و برق خود را به نمایش می‌گذارد.'),
(14, 3, 3, 'ابیسینیا', 'Aberfan', '2019-11-17', 60, 'در سال ۱۹۶۶، فاجعه آبرفان اتفاق می‌افتد و ملکه سعی می‌کند به مردمش نشان دهد که به آنها اهمیت می‌دهد.'),
(14, 3, 4, 'بابل', 'Bubbikins', '2019-11-17', 52, 'شاهزاده فیلیپ در مصاحبه‌ای شرکت می‌کند. مادرش پرنسس آلیس یونان به باکینگهام پالاس می‌آید.'),
(14, 3, 5, 'کولسیل ۲', 'Coup', '2019-11-17', 58, 'لرد مونت‌باتن از ملکه می‌خواهد که در یک کودتای سیاسی شرکت کند. ملکه سعی می‌کند بیطرف بماند.'),
(14, 3, 6, 'براد راهرو', 'Tywysog Cymru', '2019-11-17', 59, 'پرنس چارلز برای تحصیلات به ولز فرستاده می‌شود و نقش جدید خود را به عنوان شاهزاده ولز می‌پذیرد.'),
(14, 3, 7, 'تپه ماهور', 'Moondust', '2019-11-17', 56, 'فیلیپ با بحران میانسالی روبرو می‌شود و سعی می‌کند معنای زندگی خود را پیدا کند.'),
(14, 3, 8, 'بذر یاس', 'Dangling Man', '2019-11-17', 54, 'پرنس چارلز با کامیلا پارکر بولز رابطه برقرار می‌کند. خانواده سلطنتی از این رابطه ناراضی هستند.'),
(14, 3, 9, 'عدم قطعیت', 'Cri de Coeur', '2019-11-17', 55, 'پرنسس مارگارت در حال عبور از مشکلات روحی است و ملکه سعی می‌کند به او کمک کند.'),
(14, 3, 10, 'مناظره سیاسی', 'Crippled', '2019-11-17', 57, 'نخست‌وزیر ادوارد هیت با اعتصابات و مشکلات اقتصادی روبرو است. ملکه نقش خود را حفظ می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 4, 1, 'طلسم', 'Gold Stick', '2020-11-15', 57, 'مارگارت تاچر به عنوان نخست‌وزیر انتخاب می‌شود. روابط ملکه و تاچر با تنش مواجه می‌شود.'),
(14, 4, 2, 'قصر فضیلت', 'The Balmoral Test', '2020-11-15', 58, 'تاچر و خانواده سلطنتی برای تعطیلات به بالمورال می‌روند. روابط آنها در این سفر بهبود می‌یابد.'),
(14, 4, 3, 'افکت عجیب', 'Fairytale', '2020-11-15', 54, 'پرنس چارلز با لیدی دایانا اسپنسر ملاقات می‌کند. ملکه از رابطه آنها حمایت می‌کند.'),
(14, 4, 4, 'عشق مورد علاقه', 'Favourites', '2020-11-15', 59, 'پرنس چارلز و لیدی دایانا ازدواج می‌کنند. ملکه سعی می‌کود خانواده را یکپارچه نگه دارد.'),
(14, 4, 5, 'شخصیت', 'Fagan', '2020-11-15', 60, 'یک مرد معمولی به نام مایکل فاگان به کاخ باکینگهام نفوذ می‌کند و با ملکه روبرو می‌شود.'),
(14, 4, 6, 'فرض زمین', 'Terra Nullius', '2020-11-15', 56, 'ملکه و تاچر بر سر آفریقای جنوبی و تحریم‌های آپارتاید با یکدیگر اختلاف نظر دارند.'),
(14, 4, 7, 'مردم ناشناس', 'Hereditary', '2020-11-15', 58, 'پرنس چارلز و دایانا به استرالیا سفر می‌کنند. مردم عاشق دایانا می‌شوند و چارلز حسادت می‌کند.'),
(14, 4, 8, '۱۹۴۷', 'The Disappearance of a British Officer', '2020-11-15', 57, 'پرنس چارلز و کامیلا رابطه خود را ادامه می‌دهند. دایانا از این موضوع مطلع می‌شود و ناراحت می‌شود.'),
(14, 4, 9, 'آویشن', 'Thyme', '2020-11-15', 55, 'دایانا از زندگی با چارلز ناامید می‌شود و سعی می‌کود حمایت مردم را جلب کند.'),
(14, 4, 10, 'جنگ', 'The Crown', '2020-11-15', 59, 'تاچر از قدرت کناره‌گیری می‌کند. دایانا از چارلز جدا می‌شود و ملکه از او حمایت می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 5, 1, 'ملکه ویا', 'Queen Victoria Syndrome', '2022-11-09', 58, 'ملکه الیزابت در سن ۶۵ سالگی با بحران‌های شخصی و سیاسی روبرو است. جان می‌یور، نخست‌وزیر جدید، سعی می‌کند با او ارتباط برقرار کند.'),
(14, 5, 2, 'سیستم', 'The System', '2022-11-09', 56, 'رسانه‌ها از خانواده سلطنتی انتقاد می‌کنند. ملکه سعی می‌کند سیستم قدیمی را حفظ کند.'),
(14, 5, 3, 'خانواده از هم پاشیده', 'Mou Mou', '2022-11-09', 59, 'پرنس چارلز و دایانا طلاق می‌گیرند. ملکه از نابودی خانواده ناراحت است و سعی می‌کند ازدواج پسرش را مدیریت کند.'),
(14, 5, 4, 'جنگل', 'Annus Horribilis', '2022-11-09', 57, 'ملکه در سخنرانی خود سال ۱۹۹۲ را "سال وحشتناک" اعلام می‌کند. قلعه ویندزور در آتش می‌سوزد.'),
(14, 5, 5, 'راهپیمایی', 'The Way Ahead', '2022-11-09', 55, 'پرنس چارلز سعی می‌کند روابط عمومی خود را بهبود بخشد و به دنبال حمایت مردم است.'),
(14, 5, 6, 'ایپاکریت', 'Ipatiev House', '2022-11-09', 58, 'ملکه از گذشته خانواده رومانوف بازدید می‌کند. روابط ملکه و فیلیپ در این سفر بهبود می‌یابد.'),
(14, 5, 7, 'تصادف', 'No Woman''s Land', '2022-11-09', 56, 'دایانا در مصاحبه‌ای شرکت می‌کند و از زندگی با چارلز می‌گوید. ملکه از این مصاحبه ناراحت می‌شود.'),
(14, 5, 8, 'چتر دریایی', 'Gunpowder', '2022-11-09', 59, 'ملکه و خانواده سلطنتی برای جشن سالگرد ازدواج خود آماده می‌شوند. روابط چارلز و دایانا تیره می‌شود.'),
(14, 5, 9, 'طوفان', 'Coup', '2022-11-09', 54, 'نخست‌وزیر جان می‌یور از قدرت کناره‌گیری می‌کند. تونی بلر جانشین او می‌شود.'),
(14, 5, 10, 'تاج', 'The Crown', '2022-11-09', 57, 'دایانا از چارلز طلاق می‌گیرد. ملکه سعی می‌کند خانواده را متحد نگه دارد و در عین حال سلطنت را حفظ کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(14, 6, 1, 'ملکه و دی', 'Queen and Diana', '2023-11-16', 58, 'دایانا پس از طلاق از چارلز، زندگی جدیدی را آغاز می‌کند. ملکه سعی می‌کند رابطه خود با نوه‌هایش را حفظ کند.'),
(14, 6, 2, 'پاریس', 'The Parisian', '2023-11-16', 56, 'دایانا به پاریس سفر می‌کند. پاپاراتزی‌ها او را تعقیب می‌کنند و او در تونل پون د لآلما تصادف می‌کند.'),
(14, 6, 3, 'مرگ دایانا', 'Dodi', '2023-11-16', 59, 'خبر مرگ دایانا در سراسر جهان پخش می‌شود. ملکه سعی می‌کند واکنش مناسب نشان دهد.'),
(14, 6, 4, 'غبار', 'Aftermath', '2023-11-16', 57, 'ملکه و خانواده سلطنتی پس از مرگ دایانا با انتقادهای زیادی روبرو می‌شوند. تونی بلر به ملکه مشاوره می‌دهد.'),
(14, 6, 5, 'ویلیام و کیت', 'William and Kate', '2023-12-14', 55, 'پرنس ویلیام در دانشگاه سنت اندروز با کیت میدلتون آشنا می‌شود. ملکه از زندگی نوه‌اش حمایت می‌کند.'),
(14, 6, 6, 'عروسی', 'The Wedding', '2023-12-14', 58, 'ویلیام و کیت ازدواج می‌کنند. ملکه خوشحال است که خانواده سلطنتی دوباره متحد شده است.'),
(14, 6, 7, 'جشن شصت سالگی', 'Sixty Years', '2023-12-14', 56, 'ملکه الیزابت شصتمین سال سلطنت خود را جشن می‌گیرد. او از گذشته خود یاد می‌کند و به آینده سلطنت فکر می‌کند.'),
(14, 6, 8, 'بازنشستگی', 'Retirement', '2023-12-14', 59, 'پرنس فیلیپ از وظایف سلطنتی بازنشسته می‌شود. ملکه در تنهایی خود فکر می‌کند.'),
(14, 6, 9, 'سفر', 'The Journey', '2023-12-14', 57, 'ملکه الیزابت به کشورهای مشترک المنافع سفر می‌کند و با مردم آنها ملاقات می‌کند.'),
(14, 6, 10, 'پایان', 'The End', '2023-12-14', 60, 'ملکه الیزابت در سن ۹۶ سالگی در قلعه بالمورال می‌میرد. پسرش چارلز به عنوان پادشاه جدید معرفی می‌شود و سلطنت ادامه می‌یابد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(15, 1, 1, 'جشن', 'Celebration', '2018-06-03', 62, 'در جشن تولد ۸۰ سالگی لوگان روی، پدر خانواده، فرزندان برای جانشینی برنامه ریزی می‌کنند اما لوگان اعلام می‌کند بازنشسته نمی‌شود.'),
(15, 1, 2, 'نمایش افتضاح', 'Shit Show at the Fuck Factory', '2018-06-10', 59, 'پس از سکته لوگان، کندال کنترل شرکت را به دست می‌گیرد. پسر عموی بزرگ، گرگ، به خانواده می‌پیوندد.'),
(15, 1, 3, 'کمک های اولیه', 'Lifeboats', '2018-06-17', 58, 'کندال با بدهی ۳ میلیارد دلاری شرکت مواجه می‌شود. رومن سعی می‌کود وام بگیرد اما موفق نمی‌شود.'),
(15, 1, 4, 'تله زنبور', 'Sad Sack Wasp Trap', '2018-06-24', 58, 'کندال در یک مراسم خیریه سخنرانی می‌کند. شیو سعی می‌کند یک رسوایی جنسی را پنهان کند.'),
(15, 1, 5, 'رفتم به بازار', 'I Went to Market', '2018-07-01', 56, 'کندال نقشه رأی عدم اعتماد به پدرش را می‌کشد. پدربزرگ گریگوری برای شکرگزاری به نیویورک می‌آید.'),
(15, 1, 6, 'کدام طرفی؟', 'Which Side Are You On?', '2018-07-08', 58, 'کندال برای رأی‌ها لابی می‌کند. رومن سعی می‌کند یکی از اعضای بی‌طرف هیئت مدیره را متقاعد کند.'),
(15, 1, 7, 'استرلیتز', 'Austerlitz', '2018-07-15', 58, 'لوگان برای بهبود تصویرش موافقت می‌کند در رانچ کانر در نیومکزیکو جلسه خانواده درمانی برگزار کند.'),
(15, 1, 8, 'پراگ', 'Prague', '2018-07-22', 56, 'جشن مجردی تام برگزار می‌شود. رومن سعی می‌کند با دشمن قدیمی پدرش معامله کند.'),
(15, 1, 9, 'پیش از ازدواج', 'Pre-Nuptial', '2018-07-29', 58, 'خانواده برای عروسی شیو و تام در یک قلعه انگلیسی جمع می‌شوند. کندال از نقشه تصاحب خصمانه باخبر می‌شود.'),
(15, 1, 10, 'کسی گم نمی‌شود', 'Nobody Is Ever Missing', '2018-08-05', 66, 'خبر تلاش برای تصاحب شرکت پخش می‌شود. کندال پس از یک تصادف مرگبار فرار می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(15, 2, 1, 'کاخ تابستانی', 'The Summer Palace', '2019-08-11', 59, 'کندال سعی می‌کند با پدرش برای خیانتش جبران کند. لوگان مشاوره می‌گیرد. شیو سعی می‌کند نقشه‌های لوگان را بفهمد.'),
(15, 2, 2, 'ولتر', 'Vaulter', '2019-08-18', 58, 'رومن و کندال برای تعیین آینده یک استارتاپ رسانه‌ای مامور می‌شوند. گرگ اسراف‌های ATN را بررسی می‌کند.'),
(15, 2, 3, 'شکار', 'Hunting', '2019-08-25', 59, 'لوگان نقشه خرید شرکت رسانه‌ای رقیب PGM را اعلام می‌کند. گرگ نگران مصاحبه با زندگینامه‌نویس لوگان است.'),
(15, 2, 4, 'اتاق امن', 'Safe Room', '2019-09-01', 58, 'رومن برنامه آموزشی مدیریت را شروع می‌کند. جنجالی درباره یک مجری خبرساز می‌شود.'),
(15, 2, 5, 'ترن هیون', 'Tern Haven', '2019-09-08', 60, 'روی‌ها برای نهایی کردن خرید PGM به خانه خانواده پیرس می‌روند. بچه‌ها از نقشه‌هایشان منحرف می‌شوند.'),
(15, 2, 6, 'آرژستس', 'Argestes', '2019-09-15', 58, 'لوگان در کنفرانس رسانه‌ای به دنبال بستن قرارداد است. تام از شعار جدید ATN نگران است.'),
(15, 2, 7, 'بازگشت', 'Return', '2019-09-22', 58, 'روی‌ها به بریتانیا می‌روند. رومن و شیو سعی می‌کنند با مادرشان معامله کنند.'),
(15, 2, 8, 'دانمارک', 'Dundee', '2019-09-29', 57, 'لوگان برای مراسم بزرگداشت خود به دانمارک می‌رود. کندال سخنرانی احساسی می‌کند.'),
(15, 2, 9, 'دی سی', 'DC', '2019-10-06', 58, 'کندال برای شهادت در مورد رسوایی کشتی‌های کروز در واشنگتن آماده می‌شود.'),
(15, 2, 10, 'این برای من نیست', 'This Is Not for Tears', '2019-10-13', 68, 'لوگان تصمیم می‌گیرد چه کسی قربانی رسوایی کشتی‌ها شود. کندال در کنفرانس خبری علیه پدرش شهادت می‌دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(15, 3, 1, 'زمان بیداری', 'Secession', '2021-10-17', 58, 'کندال پس از شهادت علیه پدر، سعی می‌کند متحدان جدیدی پیدا کند. خانواده روی در بحران هستند.'),
(15, 3, 2, 'ماساچوست', 'Mass in Time of War', '2021-10-24', 57, 'لوگان سعی می‌کند تیم حقوقی خود را حفظ کند. کندال با املاک و دارایی‌هایش بازی می‌کند.'),
(15, 3, 3, 'قطع ارتباط', 'The Disruption', '2021-10-31', 57, 'کندال سعی می‌کند کارمندان WAYSTAR را علیه پدرش متحد کند. شیو و رومن به لندن سفر می‌کنند.'),
(15, 3, 4, 'آب شیرین', 'Lion in the Meadow', '2021-11-07', 57, 'روی‌ها به ایتالیا سفر می‌کنند. لوگان سعی می‌کند یک خرید جدید انجام دهد.'),
(15, 3, 5, 'بستنی', 'Retired Janitors of Idaho', '2021-11-14', 57, 'کندال سعی می‌کود اعضای هیئت مدیره را متقاعد کند. تام و گرگ از نفوذ خود استفاده می‌کنند.'),
(15, 3, 6, 'چه کاری می‌توانی بکنی؟', 'What It Takes', '2021-11-21', 57, 'لوگان در یک کنفرانس سیاسی شرکت می‌کند. رومن سعی می‌کند یک معامله بزرگ را نجات دهد.'),
(15, 3, 7, 'در به در', 'Too Much Birthday', '2021-11-28', 57, 'کندال جشن تولد ۴۰ سالگی خود را برگزار می‌کند. خانواده روی به دنبال نفوذ هستند.'),
(15, 3, 8, 'زنجیر', 'Chiantishire', '2021-12-05', 57, 'خانواده روی در ایتالیا برای یک عروسی جمع می‌شوند. تنش‌ها به اوج خود می‌رسد.'),
(15, 3, 9, 'بیرون ریخته شده', 'All the Bells Say', '2021-12-12', 59, 'نبرد نهایی برای کنترل شرکت در ایتالیا رخ می‌دهد. کندال، شیو و رومن علیه لوگان متحد می‌شوند اما شکست می‌خورند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(15, 4, 1, 'شرکت مزخرف', 'The Munsters', '2023-03-26', 57, 'کندال، شیو و رومن شرکت جدید خود را راه اندازی می‌کنند و با پدر رقابت می‌کنند.'),
(15, 4, 2, 'ضیافت شام', 'Rehearsal', '2023-04-02', 57, 'روی‌ها در یک مهمانی شام در لس آنجلس جمع می‌شوند. مذاکرات برای فروش شرکت ادامه دارد.'),
(15, 4, 3, 'کونر عروسی دارد', 'Connor''s Wedding', '2023-04-09', 57, 'لوگان در سفر به سوئد دچار حمله قلبی می‌شود و می‌میرد. بچه‌ها برای خداحافظی به سوئد می‌روند.'),
(15, 4, 4, 'مراقبت از برادر بزرگتر', 'Honeymoon States', '2023-04-16', 57, 'پس از مرگ لوگان، کندال، شیو و رومن کنترل شرکت را به دست می‌گیرند. رومن سقوط می‌کند.'),
(15, 4, 5, 'انتخابات', 'Kill List', '2023-04-23', 57, 'کندال و رومن سعی می‌کنند یک نامزد ریاست جمهوری را انتخاب کنند. شیو با تیم لوگان مذاکره می‌کند.'),
(15, 4, 6, 'سوئد', 'Living+', '2023-04-30', 57, 'کندال رویداد سرمایه‌گذاران LIVING+ را اجرا می‌کند. تام سعی می‌کود به بچه‌ها نزدیک شود.'),
(15, 4, 7, 'کیک تولد', 'Tailgate Party', '2023-05-07', 57, 'شیو و تام در یک مهمانی سعی می‌کنند رابطه خود را درست کنند. کندال قدرت را حفظ می‌کند.'),
(15, 4, 8, 'آمریکا دچار اشتباه می‌شود', 'America Decides', '2023-05-14', 57, 'شب انتخابات ریاست جمهوری، ATN تصمیم می‌گیرد برنده را اعلام کند. بچه‌ها بر سر این تصمیم دعوا می‌کنند.'),
(15, 4, 9, 'کلیسا', 'Church of the Divine', '2023-05-21', 57, 'مراسم تشییع جنازه لوگان برگزار می‌شود. همه شخصیت‌های اصلی برای وداع جمع می‌شوند.'),
(15, 4, 10, 'با چشم‌های باز', 'With Open Eyes', '2023-05-28', 57, 'رأی نهایی برای فروش شرکت برگزار می‌شود. کندال، شیو و رومن متحد می‌شوند اما نتیجه غیرمنتظره رقم می‌خورد. کندال بازنده می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(16, 1, 1, 'رازها', 'Secrets', '2017-12-01', 51, 'پسری به نام اریک در ویدن ناپدید می‌شود. چهار خانواده در یک شهر کوچک آلمانی با رازهای تاریک خود روبرو می‌شوند.'),
(16, 1, 2, 'دروغ', 'Lies', '2017-12-01', 46, 'اولریش به دنبال مادس، برادر گمشده خود، در غارها می‌گردد. هانا به اولریش نزدیک می‌شود.'),
(16, 1, 3, 'گذشته و حال', 'Past and Present', '2017-12-01', 47, 'در سال ۱۹۸۶، مادس ناپدید می‌شود. اولریش به عنوان پلیس مشغول تحقیق است. در سال ۲۰۱۹، یوناس سعی می‌کند حقیقت را بفهمد.'),
(16, 1, 4, 'سرنوشت های دوگانه', 'Double Lives', '2017-12-01', 51, 'رابطه مخفی هانا و اولریش فاش می‌شود. چارلوت تردید دارد که رازهای ویدن را فاش کند.'),
(16, 1, 5, 'حقیقت ها', 'Truths', '2017-12-01', 59, 'یوناس توسط نوح به اتاق زمان برده می‌شود. اولریش متوجه می‌شود که مادس ۳۳ سال پیش ناپدید شده است.'),
(16, 1, 6, 'نشانه ها', 'Signs', '2017-12-01', 45, 'چارلوت و یوناس سعی می‌کنند معمای زمان را حل کنند. رژینا با بیماری خود روبرو می‌شود.'),
(16, 1, 7, 'عبور', 'Crossings', '2017-12-01', 48, 'اولریش به سال ۱۹۵۳ سفر می‌کند. هلیگه جوان در گذشته با اولریش برخورد می‌کند.'),
(16, 1, 8, 'پاداش', 'As You Sow, So You Shall Reap', '2017-12-01', 59, 'نوح سعی می‌کند اولریش را متقاعد کند. آینده و گذشته در ویدن در هم می‌پیچد.'),
(16, 1, 9, 'همه چیز حالا', 'Everything Is Now', '2017-12-01', 55, 'یوناس به سال ۲۰۱۹ بازمی‌گردد و حقیقت ناپدید شدن مایکل را می‌فهمد. کلودیا به ویدن بازمی‌گردد.'),
(16, 1, 10, 'آلفا و امگا', 'Alpha and Omega', '2017-12-01', 56, 'یوناس سعی می‌کند از سفر در زمان جلوگیری کند اما به سال ۲۰۵۲ منتقل می‌شود. حلقه زمان تکرار می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(16, 2, 1, 'آغاز و پایان', 'Anfänge und Enden', '2019-06-21', 53, 'در سال ۲۰۵۲، یوناس سعی می‌کند به ۲۰۲۰ بازگردد. مارتا توسط همتای جهان دیگر خود کشته می‌شود.'),
(16, 2, 2, 'سفرهای تاریک', 'Dark Matter', '2019-06-21', 49, 'یوناس به سال ۲۰۲۰ بازمی‌گردد و سعی می‌کند مارتا را نجات دهد. کلودیا به دنبال راهی برای شکستن حلقه است.'),
(16, 2, 3, 'اشباح', 'Ghosts', '2019-06-21', 52, 'در سال ۱۹۵۴، نوح سعی می‌کود برادرش را نجات دهد. در سال ۲۰۲۰، مارتا از مرگ همتای خود شوکه می‌شود.'),
(16, 2, 4, 'مسافران زمان', 'The Travelers', '2019-06-21', 54, 'سفر در زمان در خانواده کانوالد فاش می‌شود. آدام به دنبال نابودی جهان است.'),
(16, 2, 5, 'پیدا کردن و گم کردن', 'Lost and Found', '2019-06-21', 52, 'کلودیا سعی می‌کند دخترش رژینا را نجات دهد. کاترینا به سال ۱۹۸۷ سفر می‌کند.'),
(16, 2, 6, 'بی نهایت زمان', 'An Endless Cycle', '2019-06-21', 57, 'در سال ۲۰۲۰، مارتا به آدام می‌پیوندد. یوناس از حقیقت جهان دیگر باخبر می‌شود.'),
(16, 2, 7, 'پرتگاه', 'The White Devil', '2019-06-21', 52, 'نوح به دنبال انتقام از کلودیا است. آدام به یوناس می‌گوید که فقط نابودی جهان می‌تواند حلقه زمان را بشکند.'),
(16, 2, 8, 'خدا کیست؟', 'Endings and Beginnings', '2019-06-21', 51, 'یوناس سعی می‌کود مارتا را از سفر در زمان بازدارد اما موفق نمی‌شود. جهان دوم ایجاد می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(16, 3, 1, 'زندگی و مرگ', 'Leben und Tod', '2020-06-27', 54, 'در جهان دوم، مارتا سعی می‌کند برادرش را نجات دهد. یوناس به دنبال حقیقت جهان‌های موازی است.'),
(16, 3, 2, 'مسافران', 'The Travelers', '2020-06-27', 52, 'یوناس و مارتا در جهان دوم با هم همکاری می‌کنند. آنها سعی می‌کنند منشاء حلقه زمان را پیدا کنند.'),
(16, 3, 3, 'آدام و ایو', 'Adam and Eva', '2020-06-27', 56, 'آدام به دنبال نابودی جهان دوم است. مارتا به عنوان ایو از جهان دوم محافظت می‌کند.'),
(16, 3, 4, 'شکل گیری', 'The Origin', '2020-06-27', 58, 'یوناس و مارتا متوجه می‌شوند که آنها منشاء حلقه زمان هستند. فرزند آنها همان زمان‌گرد است.'),
(16, 3, 5, 'زندگی و مرگ', 'Life and Death', '2020-06-27', 59, 'در جهان دوم، مارتا سعی می‌کند از مرگ برادرش جلوگیری کند. در جهان اول، یوناس به دنبال راهی برای شکستن حلقه است.'),
(16, 3, 6, 'نور و سایه', 'Light and Shadow', '2020-06-27', 50, 'یوناس و مارتا در جهان‌های موازی با هم ملاقات می‌کنند. آنها سعی می‌کنند والدین خود را نجات دهند.'),
(16, 3, 7, 'بین زمان', 'Between the Time', '2020-06-27', 57, 'در روز آخر، یوناس و مارتا سعی می‌کنند مبدأ حلقه زمان را پیدا کنند. آدام به دنبال نابودی هر دو جهان است.'),
(16, 3, 8, 'بهشت', 'Paradise', '2020-06-27', 73, 'یوناس و مارتا در تونل زمان ملاقات می‌کنند و تصمیم می‌گیرند جهان‌ها را نابود کنند تا خانواده‌هایشان آزاد شوند. حلقه زمان شکسته می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(17, 1, 1, 'مبدأ', 'The Original', '2016-10-02', 68, 'در پارک وست‌ورلد، مهمانان با هاست‌هایی که شبیه انسان هستند، تعامل می‌کنند. دولورس، یک هاست قدیمی، نشانه‌هایی از خودآگاهی نشان می‌دهد.'),
(17, 1, 2, 'چرخ و فلک', 'Chestnut', '2016-10-09', 60, 'ویلیام، مهمان جدید، به وست‌ورلد وارد می‌شود و توسط لوگان راهنمایی می‌شود. مِیو، هاست خانه اسباب‌بازی، شروع به دیدن رؤیا می‌کند.'),
(17, 1, 3, 'مسیر سرگردان', 'The Stray', '2016-10-16', 58, 'هاستی که خارج از محدوده پرسه می‌زند باعث نگرانی می‌شود. برنارد سعی می‌کد معمای رفتارهای غیرمنتظره هاست‌ها را حل کند.'),
(17, 1, 4, 'نظریه آرنولد', 'Dissonance Theory', '2016-10-23', 59, 'دولورس و ویلیام به دنبال یک مکان مخفی در کوهستان می‌گردند. فورد داستان شریک سابق خود، آرنولد را فاش می‌کند.'),
(17, 1, 5, 'تپه غرب', 'Contrapasso', '2016-10-30', 58, 'دولورس و ویلیام به پاراکریا می‌رسند و با یک مراسم وحشیانه روبرو می‌شوند. مِیو توسط تیم تعمیرات وست‌ورلد بیدار می‌شود.'),
(17, 1, 6, 'دشمن', 'The Adversary', '2016-11-06', 57, 'مِیو سعی می‌کند پناهنده شود اما نقشه‌هایش لو می‌رود. شرکت دلوس پلان‌های جدیدی برای وست‌ورلد دارد.'),
(17, 1, 7, 'بیننده', 'Trompe L''Oeil', '2016-11-13', 58, 'برنارد متوجه می‌شود که خودش یک هاست است که توسط فورد ساخته شده. ملاقات شارلوت و تریسا نقشه‌های دلوس را نشان می‌دهد.'),
(17, 1, 8, 'ردپا', 'Trace Decay', '2016-11-20', 59, 'مِیو قدرت کنترل هاست‌های دیگر را پیدا می‌کند. دولورس به یاد می‌آورد که آرنولد قتل عامی در پارک ایجاد کرده است.'),
(17, 1, 9, 'هماهنگی کامل', 'The Well-Tempered Clavier', '2016-11-27', 59, 'دولورس و ویلیام به کلیسای سفید می‌رسند. مِیو سعی می‌کند کارمند وست‌ورلد را فریب دهد.'),
(17, 1, 10, 'ذهن دوگانه', 'The Bicameral Mind', '2016-12-04', 90, 'فورد مهمانی نهایی خود را برای دلوس برگزار می‌کند. دولورس آرنولد را می‌کشد. فورد قربانی یک قتل عام توسط هاست‌ها می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(17, 2, 1, 'سفر شبانه', 'Journey Into Night', '2018-04-22', 68, 'پس از قتل عام، هاست‌ها پارک را کنترل می‌کنند. برنارد با دلفوس ملاقات می‌کند. مِیو به دنبال دخترش می‌گردد.'),
(17, 2, 2, 'بازسازی', 'Reunion', '2018-04-29', 59, 'ویلیام به عنوان انسان نجات پیدا می‌کند و سعی می‌کند هاست‌ها را نابود کند. دولورس سعی می‌کارد متحدان جدیدی پیدا کند.'),
(17, 2, 3, 'فضای مجازی', 'Virtù e Fortuna', '2018-05-06', 58, 'دولورس ارتش خود را از هاست‌های شورشی تشکیل می‌دهد. مِیو به امید پیدا کردن دخترش به پارک شوگون وارد می‌شود.'),
(17, 2, 4, 'معمای اسفینکس', 'The Riddle of the Sphinx', '2018-05-13', 69, 'ویلیام با جیمز دلفوس، پدرخانم خود، ملاقات می‌کند که در یک هاست زندانی شده است. برنارد به دنبال سلاح مخفی آرنولد می‌گردد.'),
(17, 2, 5, 'آکِشِتا', 'Akane No Mai', '2018-05-20', 59, 'مِیو در پارک شوگون با آکانه ملاقات می‌کند. در وست‌ورلد، دولورس سعی می‌کند "دره فراتر" را پیدا کند.'),
(17, 2, 6, 'فضاها', 'Phase Space', '2018-05-27', 58, 'شارلوت سعی می‌کند با دلوس تماس بگیرد. مِیو به وست‌ورلد بازمی‌گردد اما دخترش را پیدا نمی‌کند.'),
(17, 2, 7, 'خودت را بشناس', 'Les Écorchés', '2018-06-03', 60, 'برنارد متوجه می‌شود که بدنش توسط شارلوت کنترل می‌شود. دولورس با ویلیام روبرو می‌شود.'),
(17, 2, 8, 'کیتسویا', 'Kiksuya', '2018-06-10', 58, 'آکشِتا، هاستی از قبیله، داستان عشق و انتقام خود را تعریف می‌کند. مِیو نهایتاً با دخترش ملاقات می‌کند.'),
(17, 2, 9, 'نقطه ملاقات', 'Vanishing Point', '2018-06-17', 58, 'ویلیام به خود می‌آید که همسرش را کشته است. دلفوس سعی می‌کند برنارد را نجات دهد.'),
(17, 2, 10, 'مسافر', 'The Passenger', '2018-06-24', 90, 'هاست‌ها به "دره فراتر" می‌روند. دولورس سعی می‌کند به جهان واقعی فرار کند. برنارد هاست‌ها را در پارک رها می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(17, 3, 1, 'پارون', 'Parce Domine', '2020-03-15', 58, 'دولورس در جهان واقعی با شرکت اینسایت همکاری می‌کند. کالب، کارگر ساختمانی، با او برخورد می‌کند.'),
(17, 3, 2, 'زمان زمستان', 'The Winter Line', '2020-03-22', 57, 'دولورس سعی می‌کند به شرکت اینسایت نفوذ کند. مِیو در پارک واروم تحت آزمایش قرار می‌گیرد.'),
(17, 3, 3, 'کمبود مطلق', 'The Absence of Field', '2020-03-29', 58, 'کالب سعی می‌کود دولورس را نجات دهد. مِیو به دنبال انتقام از دولورس است.'),
(17, 3, 4, 'مادر مادرها', 'The Mother of Exiles', '2020-04-05', 58, 'برنارد و استابز به دنبال دولورس می‌گردند. مِیو با دولورس روبرو می‌شود اما شکست می‌خورد.'),
(17, 3, 5, 'ژانر', 'Genre', '2020-04-12', 58, 'دولورس سعی می‌کد سیستم اینسایت را نابود کند. کالب دلایل خود را برای کمک به دولورس فاش می‌کند.'),
(17, 3, 6, 'دکوراسیون', 'Decoherence', '2020-04-19', 58, 'شارلوت سعی می‌کند از خانواده خود محافظت کند. مِیو با سراف متحد می‌شوند تا دولورس را متوقف کنند.'),
(17, 3, 7, 'همدردی گذرا', 'Passed Pawn', '2020-04-26', 58, 'دولورس گذشته خود در پارک وست‌ورلد را به یاد می‌آورد. کالب با مادرش ملاقات می‌کند.'),
(17, 3, 8, 'بحران تئوری', 'Crisis Theory', '2020-05-03', 76, 'دولورس سیستم اینسایت را نابود می‌کند. شارلوت توسط مِیو کشته می‌شود. دولورس به کالب کنترل جهان را می‌دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(17, 4, 1, 'مرثیه', 'The Auguries', '2022-06-26', 53, 'هفت سال بعد، کالب مدیر امنیت است و با گروهی از هاست‌های شورشی مبارزه می‌کند. مِیو به دنبال شارلوت است.'),
(17, 4, 2, 'ولگردی', 'Well Enough Alone', '2022-07-03', 49, 'شارلوت سعی می‌کد هاست جدیدی بسازد. مِیو به پارک وست‌ورلد بازمی‌گردد.'),
(17, 4, 3, 'قرن سال', 'Années Folles', '2022-07-10', 44, 'در سال ۱۹۲۰، پارک جدیدی به نام "رؤیای تب‌دار" ساخته شده است. مِیو در این پارک زندانی می‌شود.'),
(17, 4, 4, 'نسخه', 'Generation Loss', '2022-07-17', 46, 'کالب و مِیو در پارک رؤیای تب‌دار با یکدیگر همکاری می‌کنند. شارلوت به دنبال نابودی جهان است.'),
(17, 4, 5, 'تغییر ذهن', 'Zhuangzi', '2022-07-24', 52, 'کالب از حقیقت گذشته خود مطلع می‌شود. هاست‌ها پارک وست‌ورلد را بازسازی می‌کنند.'),
(17, 4, 6, 'وفاداری', 'Fidelity', '2022-07-31', 53, 'کالب متوجه می‌شود که خودش یک هاست است. مِیو با شارلوت روبرو می‌شود.'),
(17, 4, 7, 'نقاط خط', 'Metanoia', '2022-08-07', 50, 'شارلوت جهان را تحت کنترل خود در می‌آورد. کالب و مِیو سعی می‌کنند او را متوقف کنند.'),
(17, 4, 8, 'بازگشت', 'Que Será, Será', '2022-08-14', 63, 'شارلوت در بیمارستان دچار بحران می‌شود. کالب و مِیو سرانجام موفق می‌شوند او را متوقف کنند اما کالب کشته می‌شود.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(18, 1, 1, 'مندلورین', 'The Mandalorian', '2019-11-12', 38, 'یک شکارچی جایزه‌بگیر تنها به نام مندلورین، قراردادی را برای گرفتن یک شیء ارزشمند از مشتری مرموز می‌پذیرد.'),
(18, 1, 2, 'کودک', 'The Child', '2019-11-15', 31, 'مندلورین برای محافظت از "کودک" (گروگو) از حمله شکارچیان جایزه‌بگیر فرار می‌کند و به دنبال یک مکان امن می‌گردد.'),
(18, 1, 3, 'گناه', 'The Sin', '2019-11-22', 36, 'مندلورین کودک را به مشتری تحویل می‌دهد اما بعد پشیمان می‌شود و برای نجات او به پایگاه شکارچیان بازمی‌گردد.'),
(18, 1, 4, 'پناهگاه', 'Sanctuary', '2019-11-29', 39, 'مندلورین و کودک به دهکده‌ای ساکت پناه می‌برند و به کشاورزان در برابر شکارچیان بیگانه کمک می‌کنند.'),
(18, 1, 5, 'تفنگدار', 'The Gunslinger', '2019-12-06', 33, 'مندلورین با یک شکارچی جوان به نام تورو کالیکان همکاری می‌کند تا یک قرارداد شکار را انجام دهد.'),
(18, 1, 6, 'زندانی', 'The Prisoner', '2019-12-13', 46, 'مندلورین با گروهی از مزدوران سابق برای نجات یک زندانی از یک کشتی حمل و نقل جدید همکاری می‌کند.'),
(18, 1, 7, 'حساب باز', 'The Reckoning', '2019-12-18', 41, 'کارا دون تلاش می‌کند تا مندلورین را متقاعد کند که با استفاده از کودک به عنوان طعمه، مشتری را به دام بیندازد.'),
(18, 1, 8, 'رستگاری', 'Redemption', '2019-12-27', 47, 'مندلورین با گروهی از طوفان‌نوردان می‌جنگد و کلاه خود را برای اولین بار در می‌آورد تا زخم‌هایش را التیام دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(18, 2, 1, 'مارشال', 'The Marshal', '2020-10-30', 53, 'مندلورین به دنبال بقیه جاواها و یک اژدهای کریت در تاتوئین می‌گردد تا اطلاعاتی درباره جدی پیدا کند.'),
(18, 2, 2, 'مسافر', 'The Passenger', '2020-11-06', 40, 'مندلورین با حمل تخم‌های قورباغه‌ای برای مسافری، سفر خطرناکی را به سمت غارهای یخی آغاز می‌کند.'),
(18, 2, 3, 'وارث', 'The Heiress', '2020-11-13', 44, 'مندلورین با بو کاتان و گروهش در یک کشتی حمل و نقل امپراتوری روبرو می‌شود.'),
(18, 2, 4, 'محاصره', 'The Siege', '2020-11-20', 30, 'مندلورین و کودک برای تعمیر کشتی به پایگاه نئووارو بازمی‌گردند و با خطر جدیدی روبرو می‌شوند.'),
(18, 2, 5, 'جدی', 'The Jedi', '2020-11-27', 46, 'مندلورین جدی به نام آسوکا تانو را پیدا می‌کند تا کودک را آموزش دهد.'),
(18, 2, 6, 'تراژدی', 'The Tragedy', '2020-12-04', 34, 'مندلورین کودک را به معبد جدی در تیتون می‌برد اما مورد حمله بابا فت و طوفان‌نوردان قرار می‌گیرد.'),
(18, 2, 7, 'باور', 'The Believer', '2020-12-11', 39, 'مندلورین مجبور می‌شود با میگس مین همکاری کند تا مکان یافتن جدی را پیدا کند.'),
(18, 2, 8, 'نجات', 'The Rescue', '2020-12-18', 48, 'مندلورین با تیمش به کشتی امپراتوری حمله می‌کند تا کودک را از دست مف گیدئون نجات دهد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(18, 3, 1, 'توبه', 'The Apostate', '2023-03-01', 36, 'مندلورین پس از مکاشفه‌هایش به ماندارلور بازمی‌گردد تا آبهای زنده را پیدا کند.'),
(18, 3, 2, 'معادن ماندارلور', 'The Mines of Mandalore', '2023-03-08', 44, 'مندلورین به معادن ماندارلور سفر می‌کند و با یک موجود خطرناک روبرو می‌شود.'),
(18, 3, 3, 'تبدیل', 'The Convert', '2023-03-15', 39, 'دکتر پرشینگ به کوروسانت بازمی‌گردد و توسط برنامه عفو امپراتوری استخدام می‌شود.'),
(18, 3, 4, 'برده', 'The Foundling', '2023-03-22', 44, 'مندلورین و بو کاتان برای نجات یک کودک ماندارلوری به پایگاه دزدان فضا حمله می‌کنند.'),
(18, 3, 5, 'دزد دریایی', 'The Pirate', '2023-03-29', 37, 'شورشیان فضایی به نئووارو حمله می‌کنند و گرگ کفن از مندلورین کمک می‌خواهد.'),
(18, 3, 6, 'اسلحه‌ها برای استخدام', 'Guns for Hire', '2023-04-05', 41, 'مندلورین و بو کاتان در پلازیر-۱۵ برای حل یک قتل با نژاد پرندگان همکاری می‌کنند.'),
(18, 3, 7, 'جاسوسان', 'The Spies', '2023-04-12', 48, 'مندلورین و تیمش به ماندارلور بازمی‌گردند تا با مف گیدئون نبرد کنند.'),
(18, 3, 8, 'بازگشت', 'The Return', '2023-04-19', 50, 'مندلورین و بو کاتان با مف گیدئون مبارزه می‌کنند و واترهای زنده را پیدا می‌کنند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(19, 1, 1, 'وارثان اژدها', 'The Heirs of the Dragon', '2022-08-21', 66, 'شاه ویسریس تارگرین با بحران جانشینی روبرو می‌شود. او دخترش رینیرا را به عنوان وارث خود معرفی می‌کند.'),
(19, 1, 2, 'شاهزاده سرکش', 'The Rogue Prince', '2022-08-28', 54, 'دامون تارگرین، برادر شاه، جزیره کوه سنگی را تصرف می‌کند و خود را پادشاه معرفی می‌کند.'),
(19, 1, 3, 'دومین نام خود', 'Second of His Name', '2022-09-04', 59, 'شاه ویسریس پسرش اگون را به عنوان وارث معرفی می‌کند. رینیرا با لینور ولاریون نامزد می‌شود.'),
(19, 1, 4, 'شاه دریا', 'King of the Narrow Sea', '2022-09-11', 60, 'دامون به کینگز لندینگ بازمی‌گردد و رینیرا را به یک فاحشه‌خانه می‌برد.'),
(19, 1, 5, 'ما راه را روشن می‌کنیم', 'We Light the Way', '2022-09-18', 60, 'رینیرا با لینور ولاریون ازدواج می‌کند. آلیسنت به دنبال تضعیف رینیرا است.'),
(19, 1, 6, 'شاهزاده و ملکه', 'The Princess and the Queen', '2022-09-25', 60, 'ده سال بعد، رینیرا سه پسر دارد. آلیسنت پسر خود اگون را برای تاج و تخت آماده می‌کند.'),
(19, 1, 7, 'دریفت مارک', 'Driftmark', '2022-10-02', 63, 'خانواده تارگرین به دریفت مارک سفر می‌کنند. رینیرا و دامون با یکدیگر ازدواج می‌کنند.'),
(19, 1, 8, 'ارباب جزر و مد', 'The Lord of the Tides', '2022-10-09', 67, 'شاه ویسریس در حال مرگ است. آلیسنت و رینیرا بر سر جانشینی اختلاف دارند.'),
(19, 1, 9, 'شورای سبز', 'The Green Council', '2022-10-16', 57, 'پس از مرگ ویسریس، شورا اگون را به عنوان پادشاه معرفی می‌کند و جنگ داخلی آغاز می‌شود.'),
(19, 1, 10, 'ملکه سیاه', 'The Black Queen', '2022-10-23', 62, 'رینیرا پسر خود لوسریس را از دست می‌دهد و سوگند می‌خورد انتقام بگیرد.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(19, 2, 1, 'پسر برای پسر', 'A Son for a Son', '2024-06-16', 58, 'دامون به کینگز لندینگ نفوذ می‌کند و برای انتقام، پسر آلیسنت را می‌کشد.'),
(19, 2, 2, 'رینیرای بی رحم', 'Rhaenyra the Cruel', '2024-06-23', 61, 'رینیرا با مرگ پسرش روبرو می‌شود. مردم کینگز لندینگ علیه او شورش می‌کنند.'),
(19, 2, 3, 'آسیاب سوزان', 'The Burning Mill', '2024-06-30', 57, 'جنگ داخلی در ریورلندز گسترش می‌یابد. دامون قلعه هارنهال را تصرف می‌کند.'),
(19, 2, 4, 'اژدهای سرخ و طلایی', 'The Red Dragon and the Gold', '2024-07-07', 61, 'نبرد بزرگ اژدهایان در رستون رخ می‌دهد و اژدهای رینیرا کشته می‌شود.'),
(19, 2, 5, 'نایب‌السلطنه', 'Regent', '2024-07-14', 60, 'آلیسنت به عنوان نایب‌السلطنه منصوب می‌شود. دامون نقشه جدیدی می‌کشد.'),
(19, 2, 6, 'عوام', 'Smallfolk', '2024-07-21', 59, 'مردم عادی کینگز لندینگ علیه خانواده سلطنتی شورش می‌کنند.'),
(19, 2, 7, 'قایق غارت', 'The Red Sowing', '2024-07-28', 64, 'رینیرا سعی می‌کند شوالیه‌های اژدهای جدیدی پیدا کند.'),
(19, 2, 8, 'ملکه که همیشه بود', 'The Queen Who Ever Was', '2024-08-04', 65, 'جنگ داخلی به اوج خود می‌رسد. سرانجام، رینیرا سوار بر اژدهایش می‌شود و به کینگز لندینگ حمله می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(20, 1, 1, 'زمانی که تو گم شدی', 'When You''re Lost in the Darkness', '2023-01-15', 81, 'در سال ۲۰۰۳، یک همه‌گیری قارچی جهان را نابود می‌کند. بیست سال بعد، جوئل مأمور می‌شود الی، دختری نوجوان را از منطقه قرنطینه خارج کند.'),
(20, 1, 2, 'آلوده', 'Infected', '2023-01-22', 53, 'جوئل و الی در حال سفر به سمت غرب هستند. آنها در موزه‌ای با افراد آلوده روبرو می‌شوند.'),
(20, 1, 3, 'برای مدت طولانی', 'Long, Long Time', '2023-01-29', 75, 'جوئل و الی با دو بازمانده به نام بیل و فرانک آشنا می‌شوند.'),
(20, 1, 4, 'لطفا دستم را بگیر', 'Please Hold My Hand', '2023-02-05', 45, 'جوئل و الی به کانزاس سیتی می‌رسند و با گروهی از شورشیان روبرو می‌شوند.'),
(20, 1, 5, 'تحمل کن و زنده بمان', 'Endure and Survive', '2023-02-10', 59, 'جوئل و الی از یک محاصره توسط افراد آلوده فرار می‌کنند و با قهرمان جدیدی به نام کتلیا ملاقات می‌کنند.'),
(20, 1, 6, 'خویشاوند', 'Kin', '2023-02-17', 59, 'جوئل و الی به دنبال برادر جوئل، تامی، در وایومینگ می‌گردند.'),
(20, 1, 7, 'رها شده', 'Left Behind', '2023-02-24', 51, 'الی به گذشته خود در مدرسه نظامی فکر می‌کند و با دوستش رایلی آشنا می‌شود.'),
(20, 1, 8, 'وقتی ما محتاجیم', 'When We Are in Need', '2023-03-05', 51, 'جوئل و الی به دنبال رستگاری هستند و با یک فرقه مذهبی خطرناک روبرو می‌شوند.'),
(20, 1, 9, 'به دنبال نور', 'Look for the Light', '2023-03-12', 43, 'جوئل و الی به بیمارستان شکارچیان آتش می‌رسند. جوئل الی را نجات می‌دهد و حقیقت درباره او را کشف می‌کند.');
INSERT INTO episode (title_id, season_number, episode_number, episode_name_fa, episode_name_en, release_date, duration_mins, summary) VALUES
(20, 2, 1, 'پنج سال بعد', 'Five Years Later', '2025-04-13', 52, 'پنج سال پس از وقایع فصل اول، جوئل و الی در جکسون زندگی می‌کنند. یک تهدید جدید شهر را تهدید می‌کند.'),
(20, 2, 2, 'از دست دادن', 'Loss', '2025-04-20', 55, 'الی حقیقت آنچه در بیمارستان رخ داد را می‌فهمد و با جوئل قطع رابطه می‌کند.'),
(20, 2, 3, 'انتقام', 'Revenge', '2025-04-27', 59, 'جوئل توسط یک دختر جوان به نام ابی کشته می‌شود. الی سوگند انتقام می‌خورد.'),
(20, 2, 4, 'سیاتل روز اول', 'Seattle Day One', '2025-05-04', 58, 'الی برای پیدا کردن ابی به سیاتل سفر می‌کند و با گروهی از شورشیان جدید روبرو می‌شود.'),
(20, 2, 5, 'سیاتل روز دوم', 'Seattle Day Two', '2025-05-11', 64, 'الی در بیمارستانی با افراد آلوده می‌جنگد و حقیقت جدیدی درباره سازمان واشنگتن کشف می‌کند.'),
(20, 2, 6, 'سیاتل روز سوم', 'Seattle Day Three', '2025-05-18', 56, 'الی در ساحل با ابی روبرو می‌شود و آنها مبارزه می‌کنند.'),
(20, 2, 7, 'رستگاری', 'Redemption', '2025-05-25', 70, 'الی پس از یک سال، به جکسون بازمی‌گردد و سعی می‌کند زندگی جدیدی شروع کند.');